	[2478]={
		encounterID=2478,
		instanceID=1198,
		order=3,
		name="Teera and Maruuk",
		lore="Ukhel necromancers are resurrecting legendary centaur. The spirits of the first matriarch, Teera, and the centaur's greatest warrior, Maruuk, have risen from their graves. Once their fury has abated, perhaps they can find rest again... and eternal peace.",
		dungeonEncounterID=2581,
		uiMapID=2093,
		pin={x=0.3282,y=0.6964},
		difficultyIDs={1,2,8,23,205},
		npcIDs={186338,186339},
		displayIDs={105721,105722},
		loot={
			{itemID=193677,diffs={},faction=-1},
			{itemID=193681,diffs={},faction=-1},
			{itemID=193676,diffs={},faction=-1},
			{itemID=193679,diffs={},faction=-1},
			{itemID=193678,diffs={},faction=-1},
			{itemID=193680,diffs={},faction=-1},
		},
		sections={
			{id=24770,title="Overview",body="As the progenitors of the Maruuk centaurs, Teera and Maruuk crushes their enemies with ancient tactics.\n\nAt 100 energy, Teera begins to cast |cFF2959D3|Hspell:382670|h[Gale Arrow]|h|r while Maruuk protects her with |cFF2959D3|Hspell:386063|h[Frightful Roar]|h|r.\n\nAt 100 energy, Maruuk attacks players with |cFF2959D3|Hspell:385339|h[Earthsplitter]|h|r. Teera repels players from Maruuk using |cFF2959D3|Hspell:384808|h[Guardian Wind]|h|r."},
			{id=25942,title="Tanks",body="$bullet; Maruuk often casts |cFF2959D3|Hspell:382836|h[Brutalize]|h|r on his current target.\n\n$bullet; |cFF2959D3|Hspell:385339|h[Earthsplitter]|h|r inflicts heavy damage to any player in the area on impact.\n\n$bullet; Maruuk's |cFF2959D3|Hspell:386063|h[Frightful Roar]|h|r will cause nearby players to flee.",difficultyIDs={1,2}},
			{id=24771,title="Tanks",body="$bullet; Maruuk often casts |cFF2959D3|Hspell:382836|h[Brutalize]|h|r on his current target.\n\n$bullet; |cFF2959D3|Hspell:385339|h[Earthsplitter]|h|r inflicts heavy damage to any player in the area on impact.\n\n$bullet; Maruuk's |cFF2959D3|Hspell:386063|h[Frightful Roar]|h|r will cause nearby players to flee.\n\n$bullet; |cFF2959D3|Hspell:392198|h[Ancestral Bond]|h|r increases damage dealt by Teera and Maruuk when they are more than $392198s1 yards apart.",difficultyIDs={8,23}},
			{id=24772,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:382670|h[Gale Arrow]|h|r creates damaging tornadoes that travel through the battlefield.\n\n$bullet; |cFF2959D3|Hspell:385339|h[Earthsplitter]|h|r inflicts heavy damage to any player in the area on impact."},
			{id=24773,title="Healers",body="$bullet; Maruuk often casts |cFF2959D3|Hspell:382836|h[Brutalize]|h|r on his current target.\n\n$bullet; Maruuk's |cFF2959D3|Hspell:386063|h[Frightful Roar]|h|r will cause nearby players to flee.\n\n$bullet; Teera will target random players with her |cFF2959D3|Hspell:386411|h[Quick Shot]|h|r."},
			{id=25943,title="Section 16",difficultyIDs={8,23}},
			{id=25552,title="Teera"},
			{id=25553,title="Section 6",body="$[!23\n\nOn Mythic difficulty, Tornadoes will travel back to their original location before disappearing.$]"},
			{id=25556,title="Section 9"},
			{id=25570,title="Section 16"},
			{id=25557,title="Section 10"},
			{id=25554,title="Section 7"},
			{id=25546,title="Maruuk"},
			{id=25547,title="Section 6",body="$[!23\n\nOn Mythic difficulty, Earthsplitter causes Aftershock for $395668d. $]"},
