	[2479]={
		encounterID=2479,
		instanceID=1197,
		order=5,
		name="Chrono-Lord Deios",
		lore="While the Dragon Queen seeks to restore the Aspects' powers, there are others among dragonkind who do not want to see Alexstrasza's plan succeed. Chrono-Lord Deios intends for his flight to control the timeways and to usher in the coming of the one true Aspect, whose dominion shall be... Infinite.",
		dungeonEncounterID=2559,
		uiMapID=2072,
		pin={x=0.4042,y=0.2691},
		difficultyIDs={1,2,8,23,205},
		npcIDs={184125},
		displayIDs={106056},
