		instanceID=1200,
		order=1,
		name="Eranog",
		lore="Eranog, commander of the Primalist forces, is relentless in his pursuit of power. With the Incarnates' release imminent, Eranog summons the whole of his army and will not hesitate to sacrifice his devoted followers to achieve victory.",
		dungeonEncounterID=2587,
