			{itemID=193651,diffs={},faction=-1},
		},
		sections={
			{id=24920,title="Overview",body="Telash attacks players with powerful frost magic that leaves behind |cFF2959D3|Hspell:387150 |h[Frozen Ground]|h|r. Upon reaching 100 energy, Telash charges up for  |cFF2959D3|Hspell:388008 |h[Absolute Zero]|h|r."},
			{id=24921,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:388008 |h[Absolute Zero]|h|r does heavy damage to all players, which can be reduced by |cFF2959D3|Hspell:388072 |h[Vault Rune]|h|r.\n$bullet; |cFF2959D3|Hspell:386781 |h[Frost Bomb]|h|r inflicts damage around players and creates |cFF2959D3|Hspell:387150 |h[Frozen Ground]|h|r."},
			{id=24922,title="Healers",body="$bullet; |cFF2959D3|Hspell:388008 |h[Absolute Zero]|h|r does heavy damage to all players, which can be reduced by |cFF2959D3|Hspell:388072 |h[Vault Rune]|h|r.\n$bullet; |cFF2959D3|Hspell:386781 |h[Frost Bomb]|h|r inflicts damage around players and creates |cFF2959D3|Hspell:387150 |h[Frozen Ground]|h|r.\n$bullet; |cFF2959D3|Hspell:387151 |h[Icy Devastator]|h|r will focus on one player inflicting moderate damage."},
			{id=24923,title="Tanks",body="$bullet; |cFF2959D3|Hspell:388008 |h[Absolute Zero]|h|r does heavy damage to all players, which can be reduced by |cFF2959D3|Hspell:388072 |h[Vault Rune]|h|r.\n$bullet; |cFF2959D3|Hspell:386781 |h[Frost Bomb]|h|r inflicts damage around players and creates |cFF2959D3|Hspell:387150 |h[Frozen Ground]|h|r."},
			{id=25634,title="Section 9"},
			{id=25635,title="Section 9"},
			{id=25636,title="Section 10",body="$[!23\n\nOn Mythic difficulty, Vault Runes become inactive after protecting players from Absolute Zero.$]"},
