	[2484]={
		encounterID=2484,
		instanceID=1197,
		order=3,
		name="Sentinel Talondras",
		lore="Talondras is one of the refti, a titan-forged race crafted by Keeper Tyr to work in harmony with dragonkind. Fiercely loyal to their maker, the refti were sometimes sent to distant shores to carry out important missions. Sentinel Talondras was charged with defending the route to the disc holding Tyr's memories, and is determined to keep the unworthy from laying claim to her maker's legacy.",
		dungeonEncounterID=2557,
		uiMapID=2071,
		pin={x=0.3061,y=0.7055},
		difficultyIDs={1,2,8,23,205},
		npcIDs={184124},
		displayIDs={106790},
		loot={
			{itemID=193806,diffs={},faction=-1},
			{itemID=193807,diffs={},faction=-1},
			{itemID=193808,diffs={},faction=-1},
			{itemID=193804,diffs={},faction=-1},
			{itemID=212756,diffs={},faction=-1},
		},
		sections={
			{id=24926,title="Overview",body="Sentinel Talondras begins the fight with two applications of |cFF2959D3|Hspell:372600|h[Inexorable]|h|r, each which absorbs the next stun effect cast on Talondras. \n\nWhen the fight begins, Talondras manifests |cFF2959D3|Hspell:372623|h[Resonating Orb]|h|r to stun players and begins to charge the |cFF2959D3|Hspell:372716|h[Ancient Dynamo]|h|r. \n\nIf the dynamo reaches 100 energy before being stunned, it provides |cFF2959D3|Hspell:372719|h[Titanic Empowerment]|h|r to Sentinel Talondras."},
			{id=24927,title="Tank",body="$bullet;|cFF2959D3|Hspell:372623|h[Resonating Orb]|h|r will stun any player or monster it comes into contact with.\n$bullet;|cFF2959D3|Hspell:372600|h[Inexorable]|h|r can be removed by Stun effects, causing the |cFF2959D3|Hspell:372716|h[Ancient Dynamo]|h|r to become vulnerable."},
			{id=24928,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:372623|h[Resonating Orb]|h|r will stun any unit it comes into contact with.\n$bullet;|cFF2959D3|Hspell:372600|h[Inexorable]|h|r can be removed by Stun effects, causing the |cFF2959D3|Hspell:372716|h[Ancient Dynamo]|h|r to become vulnerable."},
			{id=24929,title="Healers",body="$bullet;|cFF2959D3|Hspell:372701|h[Crushing Stomp]|h|r inflicts high damage to all players.\n$bullet;|cFF2959D3|Hspell:372718|h[Earthen Shards]|h|r causes one player to bleed for high damage over its duration."},
			{id=24935,title="Section 10",difficultyIDs={2,8,23}},
			{id=24934,title="Section 9"},
			{id=27130,title="Section 11",difficultyIDs={8,23}},
			{id=24931,title="Section 6"},
			{id=24932,title="Section 7"},
			{id=24933,title="Section 7"},
		},
	},
	[2485]={
		encounterID=2485,
		instanceID=1202,
		order=2,
		name="Kokia Blazehoof",
		lore="As Primalist forces assault the Ruby Life Pools from all sides, it falls to Kokia and her Blazebound lieutenants to capture precious eggs from overwhelmed defenders, all while spreading flame and havoc as they go.",
		dungeonEncounterID=2606,
		uiMapID=2094,
		pin={x=0.4005,y=0.4272},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189232},
		displayIDs={102552,106851},
		loot={
			{itemID=193762,diffs={},faction=-1},
			{itemID=193765,diffs={},faction=-1},
			{itemID=193767,diffs={},faction=-1},
			{itemID=193763,diffs={},faction=-1},
			{itemID=193764,diffs={},faction=-1},
			{itemID=193766,diffs={},faction=-1},
		},
		sections={
			{id=24936,title="Overview",body="Throughout the fight, Kokia alternates between hurling |cFF2959D3|Hspell:372107|h[Molten Boulders]|h|r at players and pummeling her target with |cFF2959D3|Hspell:372859|h[Searing Blows]|h|r.\n\nUpon reaching 100 energy, Kokia performs a |cFF2959D3|Hspell:372863|h[Ritual of Blazebinding]|h|r."},
			{id=24937,title="Tank",body="$bullet;|cFF2959D3|Hspell:372859|h[Searing Blows]|h|r applies additional |cFF2959D3|Hspell:372860|h[Searing Wounds]|h|r with each hit.\n$bullet;|cFF2959D3|Hspell:373017|h[Blaze Volley]|h|r inflicts significant damage to all players unless interrupted.\n$bullet;Blazebound Firestorms from |cFF2959D3|Hspell:372863|h[Ritual of Blazebinding]|h|r cast damaging abilities until defeated."},
			{id=24938,title="Damage Dealers",body="$bullet;Blazebound Firestorms from |cFF2959D3|Hspell:372863|h[Ritual of Blazebinding]|h|r cast damaging abilities until defeated.\n$bullet;|cFF2959D3|Hspell:373017|h[Blaze Volley]|h|r inflicts significant damage to all players unless interrupted.\n$bullet;|cFF2959D3|Hspell:372107|h[Molten Boulder]|h|r inflicts heavy Fire damage and knocks away any player it hits."},
			{id=24939,title="Healer",body="$bullet;|cFF2959D3|Hspell:384823|h[Inferno]|h|r inflicts significant damage to all players.\n$bullet;|cFF2959D3|Hspell:372863|h[Ritual of Blazebinding]|h|r inflicts significant damage to the targeted player.\n$bullet;|cFF2959D3|Hspell:372107|h[Molten Boulder]|h|r inflicts heavy Fire damage and knocks away any player it hits."},
			{id=24944,title="Section 9"},
			{id=24945,title="Blazebound Firestorm"},
			{id=24976,title="Section 12",difficultyIDs={1,2,8,19,23,24,150,205,216,236}},
			{id=24977,title="Section 13",difficultyIDs={8,23}},
			{id=24946,title="Section 11"},
