	[2486]={
		encounterID=2486,
		instanceID=1200,
		order=3,
		name="The Primal Council",
		lore="These masters of the elements are ruthless in their pursuit of power. Embar Firepath is as merciless as the fire she commands. Opalfang wields the might of the earth to crush her enemies. Kadros Icewrath is cold and cruel, while his sibling Dathea Stormlash is as wild and unpredictable as a raging storm.",
		dungeonEncounterID=2590,
		uiMapID=2120,
		pin={x=0.4357,y=0.7048},
		difficultyIDs={14,15,16,17},
		npcIDs={187767,187768,187771,187772},
		displayIDs={106928,107597,107598,107599},
		loot={
			{itemID=195486,diffs={},faction=-1},
			{itemID=195489,diffs={},faction=-1},
			{itemID=195484,diffs={},faction=-1},
			{itemID=194300,diffs={},faction=-1},
			{itemID=195485,diffs={},faction=-1},
			{itemID=195488,diffs={},faction=-1},
			{itemID=194301,diffs={},faction=-1},
			{itemID=195487,diffs={},faction=-1},
			{itemID=195518,diffs={},faction=-1},
		},
		sections={
			{id=24948,title="Overview",body="The Primal Council works together to wipe out players with elemental attacks. When brought to low health, council members begin channeling their Convocation spell until all members of the council are defeated.\n\nThe elemental magics of the Primal Council's abilities can interact with each other in different ways to both advantage and detriments."},
			{id=24949,title="Tanks",body="$bullet;|cFF2959D3|Hspell:372027|h[Slashing Blaze]|h|r inflicts high Fire damage to players in front of Embar.\n$bullet;|cFF2959D3|Hspell:372056|h[Crush]|h|r massively increases Physical damage taken."},
			{id=24950,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:371624|h[Conductive Mark]|h|r spreads to nearby players.\n$bullet;|cFF2959D3|Hspell:374043|h[Meteor Axes]|h|r will destroy any |cFF2959D3|Hspell:370991|h[Earthen Pillar]|h|r they hit.\n$bullet;Touching |cFF2959D3|Hspell:371514|h[Scorched Ground]|h|r removes applications of |cFF2959D3|Hspell:371836|h[Primal Blizzard]|h|r."},
			{id=24951,title="Healers",body="$bullet;|cFF2959D3|Hspell:374043|h[Meteor Axes]|h|r split damage evenly amongst players hit and destroy |cFF2959D3|Hspell:370991|h[Earthen Pillars]|h|r.\n$bullet;|cFF2959D3|Hspell:371836|h[Primal Blizzard]|h|r inflicts heavy damage to all players and can trap them in |cFF2959D3|Hspell:371591|h[Frost Tombs]|h|r."},
			{id=24952,title="Kadros Icewrath"},
			{id=25898,title="Primal Blizzard",difficultyIDs={14,15,17}},
			{id=25899,title="Section 16"},
			{id=24956,title="Primal Blizzard",body="$[!16\n\nOn Mythic difficulty, |cFF2959D3|Hspell:371514|h[Scorched Ground]|h|r is consumed when it's used to remove Primal Blizzard.$]",difficultyIDs={16}},
			{id=24957,title="Section 16"},
			{id=24955,title="Section 14"},
			{id=25585,title="Section 24"},
			{id=24958,title="Dathea Stormlash"},
			{id=25765,title="Conductive Mark",body="Dathea marks the player with lightning, inflicting $371624s3 Nature damage on impact and an additional $371624s2 Nature damage every $t2 sec for$371624d. Increases Nature damage taken by $371624s1% for each application. This effect stacks.\n\nIf an affected player comes within 5 yards of another player, the mark will duplicate to that target. Moving within 5 yards of an |cFF2959D3|Hspell:370991|h[Earthen Pillar]|h|r harmlessly removes the mark.",difficultyIDs={14,15,17}},
			{id=24961,title="Conductive Mark",body="Dathea marks the player with lightning, inflicting $371624s3 Nature damage on impact and an additional $371624s2 Nature damage every $t2 sec. Increases Nature damage taken by $371624s1% for each application. This effect stacks.\n\nIf an affected player comes within 5 yards of another player, the mark will duplicate to that target. Moving within 5 yards of an |cFF2959D3|Hspell:370991|h[Earthen Pillar]|h|r harmlessly removes the mark.\n\n$[!16 On Mythic difficulty, Conductive Mark does not expire.$]",difficultyIDs={16}},
			{id=24962,title="Section 19"},
			{id=25901,title="Section 31"},
			{id=25586,title="Section 25"},
			{id=24967,title="Opalfang"},
			{id=25900,title="Section 26",difficultyIDs={14,16,17}},
			{id=26059,title="Section 32",difficultyIDs={16}},
			{id=24969,title="Earthen Pillar",body="Opalfang erupts pillars of rock from the earth at locations of several players, inflicting $s2 Nature damage to players within $A2 yards and knocking them back.$[!15\n\nOn Heroic difficulty, Earthen Pillars erupt with |cFF2959D3|Hspell:396328|h[Quaking Pulse]|h|r.$]",difficultyIDs={15}},
			{id=26060,title="Section 33",difficultyIDs={15}},
			{id=24972,title="Section 28"},
			{id=25587,title="Section 26"},
			{id=24965,title="Embar Firepath"},
			{id=25872,title="Meteor Axes",body="Embar targets two players and hurls conjured fire axes at them, inflicting $374043s1 Fire damage split between all targets within $374043A1 yards. Leaves behind |cFF2959D3|Hspell:371514|h[Scorched Ground]|h|r on impact for $371504d.",difficultyIDs={14,17}},
			{id=25873,title="Scorched Ground",body="The impact of Embar's |cFF2959D3|Hspell:374043|h[Meteor Axes]|h|r scorches the ground for $371504d, inflicting $371514s1 Fire damage every $371514t1 sec. to players who stand in the area.\n\nThe heat dispels |cFF2959D3|Hspell:371836|h[Primal Blizzard]|h|r.",difficultyIDs={14,15,17}},
			{id=24966,title="Meteor Axes",body="Embar targets two players and hurls conjured fire axes at them, inflicting $374043s1 Fire damage split between all targets within $374043A1 yards, and increases damage taken from Meteor Axes by $375091s1% for $375091d. Leaves behind |cFF2959D3|Hspell:371514|h[Scorched Ground]|h|r on impact for $371504d.\n\n$[!15 On Heroic difficulty, Meteor Axes increase damage taken from subsequent impacts for $375091d.$]",difficultyIDs={15}},
			{id=25763,title="Scorched Ground",body="The impact of Embar's |cFF2959D3|Hspell:374043|h[Meteor Axes]|h|r scorches the ground for $371504d, inflicting $371514s1 Fire damage every $371514t1 sec. to players who stand in the area.\n\nThe heat dispels |cFF2959D3|Hspell:371836|h[Primal Blizzard]|h|r.",difficultyIDs={14,15,17}},
			{id=25869,title="Meteor Axes",body="Embar targets two players and hurls conjured fire axes at them, inflicting $374043s1 Fire damage split between all targets within $374043A1 yards, and increases damage taken from Meteor Axes by $375091s1% for $375091d. Leaves behind |cFF2959D3|Hspell:371514|h[Scorched Ground]|h|r on impact for $371504d.",difficultyIDs={16}},
			{id=25871,title="Scorched Ground",body="|cFF2959D3|Hspell:374043|h[Meteor Axes]|h|r scorch the ground, inflicting $371514s1 Fire damage every $371514t1 sec. to players within the area.\n\n$[!16 On Mythic difficulty, Scorched Ground is consumed when it's used to remove |cFF2959D3|Hspell:371836|h[Primal Blizzard]|h|r.$]",difficultyIDs={16}},
			{id=24975,title="Section 24"},
			{id=25588,title="Section 27"},
		},
	},
	[2487]={
		encounterID=2487,
		instanceID=1197,
		order=2,
		name="Bromach",
		lore="The burly Bromach is chieftain of the Stonevault troggs, a brutal bunch who believe that Uldaman's treasures belong to them. While Bromach has a particular distaste for meddling dwarves, he's determined that no outsiders will get past him.",
		dungeonEncounterID=2556,
		uiMapID=2071,
		pin={x=0.5945,y=0.64},
		difficultyIDs={1,2,8,23,205},
		npcIDs={184018},
		displayIDs={77268,92697,107143},
		loot={
			{itemID=193813,diffs={},faction=-1},
			{itemID=193668,diffs={},faction=-1},
