			{itemID=193818,diffs={},faction=-1},
			{itemID=193809,diffs={},faction=-1},
			{itemID=193814,diffs={},faction=-1},
		},
		sections={
			{id=24979,title="Overview",body="Bromach, Chieftan of the Stonevault Troggs, commands his kin to assault players. Periodically, he will call forth a |cFF2959D3|Hspell:369615|h[Quaking Totem]|h|r and bolster all troggs by casting |cFF2959D3|Hspell:369754|h[Bloodlust]|h|r."},
			{id=24980,title="Tanks",body="$bullet;|cFF2959D3|Hspell:369615|h[Quaking Totem]|h|r causes a |cFF2959D3|Hspell:369660|h[Tremor]|h|r when it is destroyed.\n$bullet;|cFF2959D3|Hspell:369605|h[Call of the Deep]|h|r summons many troggs that can quickly overwhelm the party.\n$bullet;|cFF2959D3|Hspell:369703|h[Thundering Slam]|h|r inflicts high damage to nearby players."},
			{id=24981,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:369615|h[Quaking Totem]|h|r causes a |cFF2959D3|Hspell:369660|h[Tremor]|h|r when it is destroyed.\n$bullet;|cFF2959D3|Hspell:369703|h[Thundering Slam]|h|r inflicts high damage to nearby players."},
			{id=24982,title="Healers",body="$bullet;|cFF2959D3|Hspell:369615|h[Quaking Totem]|h|r inflicts damage to all players with |cFF2959D3|Hspell:369610|h[Shocking Quake]|h|r as long as it is alive.\n$bullet;|cFF2959D3|Hspell:369703|h[Thundering Slam]|h|r inflicts high damage to nearby players."},
			{id=24986,title="Stonevault Ambusher"},
			{id=24987,title="Section 12"},
			{id=24988,title="Stonevault Geomancer"},
			{id=24989,title="Section 14",difficultyIDs={2,8,23}},
			{id=25913,title="Section 15"},
			{id=24990,title="Section 6"},
			{id=24991,title="Section 9"},
			{id=24992,title="Section 10",body="$[!8,23,\n\nOn Mythic difficulty, Tremor only affects troggs within $369660A1 yards.$]"},
			{id=24993,title="Section 7"},
			{id=24994,title="Section 8"},
		},
	},
	[2488]={
		encounterID=2488,
		instanceID=1202,
		order=1,
		name="Melidrussa Chillworn",
		lore="Melidrussa Chillworn leads the Primalist infusion efforts in the Ruby Life Pools. Her fervent belief is that she is protecting young dragon eggs from the influence of the titans and cleansing them from the stain of Order magic. She will stop at nothing to fulfill her calling and return the eggs to what she believes is their natural state.",
		dungeonEncounterID=2609,
		uiMapID=2095,
