			{itemID=193728,diffs={},faction=-1},
		},
		sections={
			{id=24995,title="Overview",body="$[1,2,24,205,216Melidrussa assaults players with |cFF2959D3|Hspell:396044|h[Hailburst]|h|r and |cFF2959D3|Hspell:372851|h[Chillstorm]|h|r. After reaching $385641s1% health and $385641s2% health, Melidrussa calls forth Infused Whelps to assist her. These whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target with each attack.$]$[8,23Melidrussa assaults players with |cFF2959D3|Hspell:396044|h[Hailburst]|h|r and |cFF2959D3|Hspell:372851|h[Chillstorm]|h|r. After reaching $385641s1% health and $385641s2% health, Melidrussa begins a |cFF2959D3|Hspell:373680|h[Frost Overload]|h|r and calls forth Infused Whelps to assist her. These whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target with each attack.$]"},
			{id=26045,title="Tank",body="$bullet;|cFF2959D3|Hspell:373046|h[Awaken Whelps]|h|r causes many Infused Whelps to swarm the party.\n$bullet;Melidrussa's Infused Whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target until defeated.",difficultyIDs={1,2,24}},
			{id=26046,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:373046|h[Awaken Whelps]|h|r causes many Infused Whelps to swarm the party.\n$bullet;|cFF2959D3|Hspell:372851|h[Chillstorm]|h|r and |cFF2959D3|Hspell:396044|h[Hailburst]|h|r cause significant damage.",difficultyIDs={1,2,24}},
			{id=26047,title="Healer",body="$bullet;|cFF2959D3|Hspell:372851|h[Chillstorm]|h|r and |cFF2959D3|Hspell:396044|h[Hailburst]|h|r cause significant damage.\n$bullet;Melidrussa's Infused Whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target until defeated.",difficultyIDs={1,2,24}},
			{id=24996,title="Tank",body="$bullet;|cFF2959D3|Hspell:373046|h[Awaken Whelps]|h|r causes many Infused Whelps to swarm the party.\n$bullet;Melidrussa's Infused Whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target until defeated.\n$bullet;|cFF2959D3|Hspell:373680|h[Frost Overload]|h|r becomes deadly quickly unless stopped.",difficultyIDs={8,23}},
