			{id=24998,title="Healer",body="$bullet;|cFF2959D3|Hspell:372851|h[Chillstorm]|h|r and |cFF2959D3|Hspell:396044|h[Hailburst]|h|r cause significant damage.\n$bullet;|cFF2959D3|Hspell:373680|h[Frost Overload]|h|r becomes deadly quickly unless stopped.\n$bullet;Melidrussa's Infused Whelps apply |cFF2959D3|Hspell:1305233|h[Cold Claws]|h|r to their current target until defeated.",difficultyIDs={8,23}},
			{id=24999,title="Section 5"},
