	[2489]={
		encounterID=2489,
		instanceID=1199,
		order=2,
		name="Forgemaster Gorek",
		lore="As one of the Djaradin's most distinguished craftsmen, Forgemaster Gorek now resides in his sweltering chamber of the black dragon barracks. There, he harnesses the igneous power of the massive forge to construct deadly weaponry.",
		dungeonEncounterID=2612,
		uiMapID=2081,
		pin={x=0.3386,y=0.6566},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189478},
		displayIDs={107189},
		loot={
			{itemID=193785,diffs={},faction=-1},
			{itemID=193783,diffs={},faction=-1},
			{itemID=193784,diffs={},faction=-1},
			{itemID=193780,diffs={},faction=-1},
			{itemID=193782,diffs={},faction=-1},
			{itemID=193781,diffs={},faction=-1},
			{itemID=194508,diffs={24},faction=-1},
		},
		sections={
			{id=25104,title="Overview",body="Those who interrupt the Forgemaster's work will be met with deadly weapons and raining fire. Periodically, Gorek forges a |cFF2959D3|Hspell:374812|h[Blazing Aegis]|h|r during |cFF2959D3|Hspell:374635|h[Might of the Forge]|h|r and hurls the infernal shield at players in a spectacle of flames."},
			{id=25105,title="Tank",body="$bullet;|cFF2959D3|Hspell:374812|h[Blazing Aegis]|h|r triggers eruptions in four directions around the target's location.\n$bullet;|cFF2959D3|Hspell:374535|h[Heated Swings]|h|r inflicts massive Physical and Fire damage."},
			{id=25106,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:374812|h[Blazing Aegis]|h|r triggers eruptions in four directions around the target's location.\n$bullet;|cFF2959D3|Hspell:377995|h[Forgestorm]|h|r inflicts heavy Fire damage to players struck."},
			{id=25107,title="Healer",body="$bullet;|cFF2959D3|Hspell:374812|h[Blazing Aegis]|h|r triggers eruptions in four directions around the target's location.\n$bullet;|cFF2959D3|Hspell:374635|h[Might of the Forge]|h|r and |cFF2959D3|Hspell:374640|h[Blazing Hammer]|h|r inflict heavy damage to the party."},
			{id=25056,title="Section 2"},
			{id=25085,title="Section 3"},
			{id=26070,title="Section 4",difficultyIDs={1,2,24}},
			{id=26071,title="Section 11"},
			{id=25086,title="Section 4",body="$[!8,23 \nOn Mythic difficulty, Blazing Aegis bounces to two additional players.$]",difficultyIDs={8,23}},
