	[2490]={
		encounterID=2490,
		instanceID=1199,
		order=1,
		name="Chargath, Bane of Scales",
		lore="This veteran dragon hunter's title was given ages ago as a mark of legend. While the Qalashi hunters under his command train, he plans their next offensive and awaits with eager anticipation the opportunity to display his expertise.",
		dungeonEncounterID=2613,
		uiMapID=2080,
		pin={x=0.4319,y=0.6657},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189340},
		displayIDs={108248},
		loot={
			{itemID=193771,diffs={},faction=-1},
			{itemID=193768,diffs={},faction=-1},
			{itemID=193769,diffs={},faction=-1},
			{itemID=193727,diffs={},faction=-1},
			{itemID=193772,diffs={},faction=-1},
		},
		sections={
			{id=26041,title="Overview",body="As an expert in hunting winged beasts, Chargath utilizes |cFF2959D3|Hspell:373424|h[Grounding Spears]|h|r rigged with |cFF2959D3|Hspell:374482|h[Grounding Chains]|h|r to lock his foes down.\n\nUpon reaching 100 energy, Chargath unleashes |cFF2959D3|Hspell:375056|h[Fiery Focus]|h|r on his target. During this time, Chargath loses sight of his surroundings and falls vulnerable to |cFF2959D3|Hspell:388523|h[Fetter]|h|r."},
			{id=26042,title="Tanks",body="$bullet; |cFF2959D3|Hspell:375056|h[Fiery Focus]|h|r inflicts heavy damage and can be interrupted with |cFF2959D3|Hspell:374638|h[Fetter]|h|r.\n$bullet; |cFF2959D3|Hspell:373767|h[Magma Wave]|h|r travels out in a straight line in front of Chargath.",difficultyIDs={1,2,24}},
			{id=25030,title="Tanks",body="$bullet; |cFF2959D3|Hspell:375056|h[Fiery Focus]|h|r inflicts heavy damage and can be interrupted with |cFF2959D3|Hspell:389080|h[Fetter]|h|r.\n$bullet; |cFF2959D3|Hspell:373767|h[Magma Wave]|h|r travels out in a straight line in front of Chargath.",difficultyIDs={8,23}},
			{id=26043,title="Healers",body="$bullet; |cFF2959D3|Hspell:373733|h[Dragon Strike]|h|r inflicts high damage and causes the target to bleed.\n$bullet; When broken, |cFF2959D3|Hspell:374482|h[Grounding Chain]|h|r will cause |cFF2959D3|Hspell:389059|h[Slag Eruption]|h|r.",difficultyIDs={1,2,24}},
			{id=25029,title="Healers",body="$bullet; |cFF2959D3|Hspell:373733|h[Dragon Strike]|h|r inflicts high damage and causes the target to bleed.\n$bullet; When broken, |cFF2959D3|Hspell:374482|h[Grounding Chain]|h|r will cause |cFF2959D3|Hspell:395656|h[Slag Eruption]|h|r.",difficultyIDs={8,23}},
			{id=26044,title="Damage Dealers",body="$bullet; When tripped, |cFF2959D3|Hspell:374482|h[Grounding Chain]|h|r will apply |cFF2959D3|Hspell:374638|h[Fetter]|h|r to the tripped target.\n$bullet; |cFF2959D3|Hspell:373424|h[Grounding Spear]|h|r leaves behind |cFF2959D3|Hspell:374854|h[Erupted Ground]|h|r where it strikes the floor.",difficultyIDs={1,2,24}},
			{id=25028,title="Damage Dealers",body="$bullet; When broken, |cFF2959D3|Hspell:374482|h[Grounding Chain]|h|r will cause |cFF2959D3|Hspell:389080|h[Fetter]|h|r.\n$bullet; |cFF2959D3|Hspell:373424|h[Grounding Spear]|h|r leaves behind |cFF2959D3|Hspell:374854|h[Erupted Ground]|h|r where it strikes the floor.",difficultyIDs={8,23}},
			{id=25087,title="Section 13",body="$[!8,23 \nOn Mythic difficulty, Chargath throws a Grounding Spear on up to 3 players.$]",difficultyIDs={8,23}},
			{id=25109,title="Section 15"},
			{id=25108,title="Section 14"},
			{id=25748,title="Section 14",body="$[!8,23 \nOn Mythic difficulty, 3 stacks of Fetter stuns Chargath and increases his damage taken by $388523s2% for $388523d.$]",difficultyIDs={8,23}},
			{id=25747,title="Section 13",difficultyIDs={8,23}},
			{id=25751,title="Section 13",difficultyIDs={1,2,24}},
