		sections={
			{id=25032,title="Overview",body="Kurog Grimtotem gains increasing dominance over an element while nearby its altar within The Primal Convergence. Upon reaching 100 energy, Kurog summons two elementals according to his levels of elemental dominance.\n\nAfter summoning forth an elemental from each altar, Kurog achieves |cFF2959D3|Hspell:396241|h[Primal Attunement]|h|r."},
			{id=25033,title="Damage Dealers",body="$bullet;Earth Breakers continually cast |cFF2959D3|Hspell:377780|h[Skeletal Fractures]|h|r.\n$bullet;The longer Kurog's elementals remain alive, the more damage they do.",difficultyIDs={14,15,17}},
			{id=25994,title="Damage Dealers",body="$bullet;Earth Breakers continually cast |cFF2959D3|Hspell:377780|h[Skeletal Fractures]|h|r.\n$bullet;The longer Kurog's elementals remain alive, the more damage they do.\n$bullet;Each time Kurog approaches a primal altar or casts an ultimate ability, he summons an elemental.",difficultyIDs={16}},
			{id=25034,title="Healers",body="$bullet;While next to a Primal Altar, Kurog Grimtotem continually inflicts that altar's elemental damage to all players.",difficultyIDs={14,17}},
			{id=25996,title="Healers",body="$bullet;While next to a Primal Altar, Kurog Grimtotem continually inflicts that altar's elemental damage to all players.\n$bullet;When Kurog Grimtotem moves between active altars, he casts |cFF2959D3|Hspell:374861|h[Elemental Shift]|h|r.",difficultyIDs={15,16}},
			{id=25035,title="Tanks",body="$bullet;|cFF2959D3|Hspell:372158|h[Sundering Strike]|h|r applies stacking Physical damage over time.\n$bullet;While not next to an active Primal Altar, Kurog Grimtotem casts |cFF2959D3|Hspell:371971|h[Elemental Surge]|h|r.",difficultyIDs={14,15,17}},
			{id=25995,title="Tanks",body="$bullet;|cFF2959D3|Hspell:372158|h[Sundering Strike]|h|r applies stacking Physical damage over time.\n$bullet;While not next to an active Primal Altar, Kurog Grimtotem casts |cFF2959D3|Hspell:371971|h[Elemental Surge]|h|r.\n$bullet;Each time Kurog approaches a primal altar or casts an ultimate ability, he summons an elemental.",difficultyIDs={16}},
			{id=25036,title="Stage One: Elemental Dominance",body="Kurog gains new abilities while near an elemental altar in The Primal Convergence."},
