	[2492]={
		encounterID=2492,
		instanceID=1203,
		order=1,
		name="Leymor",
		lore="Leymor was born of a humble seedling that Malygos found in a pool of ley energy. Once but a small sprout in Sindragosa's garden, over millenia Leymor has shot up like a weed. Left to its own devices, the looming giant would surely overrun the entirety of the Azure Vault.",
		dungeonEncounterID=2582,
		uiMapID=2073,
		pin={x=0.3726,y=0.54},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={186644},
		displayIDs={107127},
		loot={
			{itemID=193633,diffs={},faction=-1},
