			{itemID=193637,diffs={},faction=-1},
		},
		sections={
			{id=25092,title="Overview",body="Leymor disrupts intruders by growing |cFF2959D3|Hspell:374364|h[Ley-Line Sprouts]|h|r, which damage players nearby them.\n\nEach of the surviving |cFF2959D3|Hspell:374364|h[Ley-Line Sprouts]|h|r increase the damage of Leymor's next |cFF2959D3|Hspell:374720|h[Consuming Stomp]|h|r."},
			{id=25093,title="Tanks",body="$bullet;|cFF2959D3|Hspell:374720|h[Consuming Stomp]|h|r does increased damage for each |cFF2959D3|Hspell:374364|h[Ley-Line Sprout]|h|r that has not been destroyed.\n$bullet;|cFF2959D3|Hspell:386660|h[Erupting Fissure]|h|r strikes players in front of Leymor for significant damage.\n$bullet;|cFF2959D3|Hspell:374788|h[Infused Strike]|h|r inflicts high Arcane damage to Leymor's current target."},
			{id=25094,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:374720|h[Consuming Stomp]|h|r does increased damage for each |cFF2959D3|Hspell:374364|h[Ley-Line Sprout]|h|r that has not been destroyed.\n$bullet;|cFF2959D3|Hspell:386660|h[Erupting Fissure]|h|r strikes players in front of Leymor for significant damage."},
			{id=25095,title="Healers",body="$bullet;|cFF2959D3|Hspell:374720|h[Consuming Stomp]|h|r does increased damage for each |cFF2959D3|Hspell:374364|h[Ley-Line Sprout]|h|r that has not been destroyed.\n$bullet;|cFF2959D3|Hspell:386660|h[Erupting Fissure]|h|r strikes players in front of Leymor for significant damage."},
