	[2494]={
		encounterID=2494,
		instanceID=1199,
		order=3,
		name="Magmatusk",
		lore="The djaradin discovered many of Neltharion's secrets while plundering Neltharus. An experimental potion gone awry created Magmatusk, a behemoth of a mammoth bent on sheer destruction.",
		dungeonEncounterID=2610,
		uiMapID=2080,
		pin={x=0.6686,y=0.6363},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={181861},
		displayIDs={102604},
		loot={
			{itemID=193786,diffs={},faction=-1},
			{itemID=193787,diffs={},faction=-1},
			{itemID=193788,diffs={},faction=-1},
			{itemID=193790,diffs={},faction=-1},
			{itemID=193789,diffs={},faction=-1},
		},
		sections={
			{id=25160,title="Overview",body="Magmatusk builds Magma energy during battle, triggering |cFF2959D3|Hspell:374365|h[Volatile Mutation]|h|r upon reaching 100 Magma. Every time |cFF2959D3|Hspell:374365|h[Volatile Mutation]|h|r is triggered another |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r will grow, empowering Magmatusk's abilities."},
			{id=25161,title="Tanks",body="$bullet;|cFF2959D3|Hspell:375449|h[Blazing Charge]|h|r releases a |cFF2959D3|Hspell:375535|h[Lava Wave]|h|r for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk.\n$bullet;|cFF2959D3|Hspell:375890|h[Magma Eruption's]|h|r duration is increased for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk."},
			{id=25162,title="Healers",body="$bullet;|cFF2959D3|Hspell:375449|h[Blazing Charge]|h|r releases a |cFF2959D3|Hspell:375535|h[Lava Wave]|h|r for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk.\n$bullet;|cFF2959D3|Hspell:375890|h[Magma Eruption's]|h|r duration is increased for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk."},
			{id=25163,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:375449|h[Blazing Charge]|h|r releases a |cFF2959D3|Hspell:375535|h[Lava Wave]|h|r for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk.\n$bullet;|cFF2959D3|Hspell:375890|h[Magma Eruption's]|h|r duration is increased for every application of |cFF2959D3|Hspell:374410|h[Magma Tentacle]|h|r on Magmatusk."},
			{id=25164,title="Section 5"},
			{id=25165,title="Section 6"},
			{id=25166,title="Section 7"},
			{id=25167,title="Section 8"},
