	[2495]={
		encounterID=2495,
		instanceID=1201,
		order=3,
		name="Crawth",
		lore="The Lish Llrath, or Talon Toss, arena is quite literally for the birds these days. Crawth has taken up residence in the center of the arena and has no immediate plans to move out soon. Let's see if we can get her to play ball... and leave.",
		dungeonEncounterID=2564,
		uiMapID=2098,
		pin={x=0.4679,y=0.3695},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={191736},
		displayIDs={64923},
		loot={
			{itemID=193719,diffs={},faction=-1},
			{itemID=193720,diffs={},faction=-1},
			{itemID=193718,diffs={},faction=-1},
			{itemID=193723,diffs={},faction=-1},
			{itemID=193721,diffs={},faction=-1},
			{itemID=193722,diffs={},faction=-1},
			{itemID=258531,diffs={2,23},faction=-1},
		},
		sections={
			{id=25203,title="Overview",body="Nesting on the sporting grounds of the old academy, Crawth loudly and violently objects to those that would reclaim the space. Unbeknownst to the massive bird, the goals of the ancient arena still contain some of their original power..."},
			{id=25204,title="Tanks",body="$bullet; |cFF2959D3|Hspell:376997|h[Savage Peck]|h|r inflicts high damage over time.\n$bullet; Scoring goals during |cFF2959D3|Hspell:377182|h[Play Ball!]|h|r can activate the field's |cFF2959D3|Hspell:376448|h[Firestorm]|h|r or |cFF2959D3|Hspell:376467|h[Gale Force]|h|r.\n$bullet; |cFF2959D3|Hspell:377034|h[Overpowering Gust]|h|r knocks away players in front of Crawth."},
			{id=25205,title="Damage Dealers",body="$bullet; Scoring goals during |cFF2959D3|Hspell:377182|h[Play Ball!]|h|r can activate the field's |cFF2959D3|Hspell:376448|h[Firestorm]|h|r or |cFF2959D3|Hspell:376467|h[Gale Force]|h|r.\n$bullet; |cFF2959D3|Hspell:377034|h[Overpowering Gust]|h|r knocks away players in front of Crawth.\n$bullet; |cFF2959D3|Hspell:377004|h[Deafening Screech]|h|r interrupts spells and silences targets that are currently casting."},
			{id=25206,title="Healers",body="$bullet; Scoring goals during |cFF2959D3|Hspell:377182|h[Play Ball!]|h|r can activate the field's |cFF2959D3|Hspell:376448|h[Firestorm]|h|r or |cFF2959D3|Hspell:376467|h[Gale Force]|h|r.\n$bullet; |cFF2959D3|Hspell:377034|h[Overpowering Gust]|h|r knocks away players in front of Crawth.\n$bullet; |cFF2959D3|Hspell:377004|h[Deafening Screech]|h|r interrupts spells and silences targets that are currently casting."},
			{id=25210,title="Section 8"},
			{id=25214,title="Goal of the Searing Blaze"},
			{id=25211,title="Section 9",body="$[!23\n\nOn Mythic difficulty, after goal is scored Firestorm continues to barrage the arena until the end of combat.$]"},
			{id=35411,title="Section 16"},
			{id=25215,title="Goal of the Rushing Winds"},
			{id=25212,title="Section 10",body="$[!23\n\nOn Mythic difficulty, after goal is scored Gale Force continues to affect the arena until the end of combat.$]"},
