	[2497]={
		encounterID=2497,
		instanceID=1198,
		order=2,
		name="The Raging Tempest",
		lore="Violent storm winds ravage the Ohn'ahran plains. Balakar's stormcasters have coalesced the tempest's fury into an avatar of the storm. The Raging Tempest continues to gather power, not just to devastate the battlefield but the entire Dragon Isles. Unchecked, Primalist chaos will reign on the plains.",
		dungeonEncounterID=2636,
		uiMapID=2093,
		pin={x=0.5343,y=0.7704},
		difficultyIDs={1,2,8,23,205},
		npcIDs={191372,191500},
		displayIDs={107145},
		loot={
			{itemID=193697,diffs={},faction=-1},
			{itemID=193699,diffs={},faction=-1},
			{itemID=193696,diffs={},faction=-1},
			{itemID=193698,diffs={},faction=-1},
			{itemID=193700,diffs={},faction=-1},
		},
		sections={
			{id=25217,title="Overview",body="The Raging Tempest brims with |cFF2959D3|Hspell:382630|h[Uncontrollable Energy]|h|r that manifests itself in the form of several lightning orbs that grant |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r. Upon reaching 100 energy, The Raging Tempest channels a powerful |cFF2959D3|Hspell:384620|h[Electrical Storm]|h|r to decimate its foes."},
			{id=25219,title="Damage Dealers",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players.",difficultyIDs={1,2}},
			{id=25220,title="Healer",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players.\n$bullet;|cFF2959D3|Hspell:384620|h[Electrical Storm]|h|r inflicts heavy damage to all players.",difficultyIDs={1,2}},
			{id=25218,title="Tank",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players.\n$bullet;The Raging Tempest inflicts heavy damage while affected by |cFF2959D3|Hspell:384686|h[Energy Surge]|h|r",difficultyIDs={1,2}},
			{id=25441,title="Damage Dealers",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players and destroys nearby lightning orbs.",difficultyIDs={8,23}},
			{id=25442,title="Healer",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players and destroys nearby lightning orbs.\n$bullet;|cFF2959D3|Hspell:384620|h[Electrical Storm]|h|r inflicts heavy damage to all players.",difficultyIDs={8,23}},
			{id=25443,title="Tank",body="$bullet;The Raging Tempest periodically fires off lightning orbs which grant players |cFF2959D3|Hspell:382628|h[Surge of Power]|h|r.\n$bullet;|cFF2959D3|Hspell:384316|h[Lightning Strike]|h|r inflicts heavy damage to nearby players and destroys nearby lightning orbs.\n$bullet;The Raging Tempest inflicts heavy damage while affected by |cFF2959D3|Hspell:384686|h[Energy Surge]|h|r",difficultyIDs={8,23}},
			{id=26017,title="Section 15",difficultyIDs={8,23}},
			{id=25436,title="Electrical Storm"},
