	[2498]={
		encounterID=2498,
		instanceID=1198,
		order=1,
		name="Granyth",
		lore="Granyth casts his shadow over the plains of Ohn'ahra, appearing as an omen of death and destruction. As battles between centaur clans rage across the plains, he knows it is time to destroy his ancient enemies once and for all. Soon he will land on the battlefield. Clan Shikaar's ballistae will be ready.",
		dungeonEncounterID=2637,
		uiMapID=2093,
		pin={x=0.7214,y=0.5128},
		difficultyIDs={1,2,8,23,205},
