		sections={
			{id=25222,title="Overview",body="Granyth assaults players with earthen powers. Upon reaching 100 energy, he attempts to crush his foes with a massive, ongoing |cFF2959D3|Hspell:388283|h[Eruption]|h|r."},
			{id=25223,title="Tanks",body="$bullet;|cFF2959D3|Hspell:388283|h[Eruption]|h|r inflicts more and more damage to all players until it is interrupted.\n$bullet;|cFF2959D3|Hspell:385916|h[Tectonic Stomp]|h|r inflicts high Nature damage to nearby players and knocks them away."},
			{id=25224,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:385916|h[Tectonic Stomp]|h|r inflicts high Nature damage to nearby players and knocks them away.\n$bullet;Nokhud Saboteurs attempt to |cFF2959D3|Hspell:386490|h[Dismantle]|h|r Dragonkiller Lances to prevent them from firing.\n$bullet;Shikaar Lancers can be instructed to fire the |cFF2959D3|Hspell:386530|h[Dragonkiller Lance]|h|r.",difficultyIDs={8,23}},
			{id=25770,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:385916|h[Tectonic Stomp]|h|r inflicts high Nature damage to nearby players and knocks them away.\n$bullet;Shikaar Lancers can be instructed to fire the |cFF2959D3|Hspell:386530|h[Dragonkiller Lance]|h|r.",difficultyIDs={1,2}},
			{id=25225,title="Healers",body="$bullet;|cFF2959D3|Hspell:388283|h[Eruption]|h|r inflicts more and more damage to all players until it is interrupted.\n$bullet;|cFF2959D3|Hspell:388817|h[Shards of Stone]|h|r inflicts unavoidable damage on all players.\n$bullet;Shikaar Lancers can be instructed to fire the |cFF2959D3|Hspell:386530|h[Dragonkiller Lance]|h|r."},
