	[2500]={
		encounterID=2500,
		instanceID=1200,
		order=2,
		name="Terros",
		lore="Primalists sought to pull Terros, an unyielding force of destruction, from the elemental plane. However, their ritual was interrupted. Trapped between two worlds, this hulking terror seeks to free himself and obliterate everything in his path.",
		dungeonEncounterID=2639,
		uiMapID=2122,
		pin={x=0.2169,y=0.759},
		difficultyIDs={14,15,16,17},
		npcIDs={190496},
		displayIDs={106344},
		loot={
			{itemID=194303,diffs={},faction=-1},
