		instanceID=1202,
		order=3,
		name="Kyrakka and Erkhart Stormvein",
		lore="Kyrakka and Erkhart roam the skies above the Ruby Life Pools coordinating attacks on the shrine below, while also taking out any interfering dragons. If left unchecked, they will burn the Life Pools to the ground and blow the remaining ash away in a cleansing elemental storm.",
		dungeonEncounterID=2623,
		uiMapID=2094,
		pin={x=0.2075,y=0.1814},
