	[2504]={
		encounterID=2504,
		instanceID=1204,
		order=1,
		name="Watcher Irideus",
		lore="Tasked by Keeper Tyr to protect and maintain the Halls of Infusion, Watcher Irideus has performed his duties to perfection... until now. Caught off guard by the Primalists' incursion, he was overwhelmed by the elemental forces they unleashed. A mistake he does not intend to make again.",
		dungeonEncounterID=2615,
		uiMapID=2082,
		pin={x=0.6165,y=0.3534},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189719},
		displayIDs={106801,109168},
		loot={
			{itemID=193743,diffs={},faction=-1},
			{itemID=193745,diffs={},faction=-1},
			{itemID=193744,diffs={},faction=-1},
			{itemID=193747,diffs={},faction=-1},
			{itemID=193746,diffs={},faction=-1},
			{itemID=200108,diffs={},faction=-1},
		},
		sections={
			{id=25383,title="Overview",body="Watcher Irideus overcharges foes with |cFF2959D3|Hspell:389179|h[Power Overload]|h|r, and harries them with |cFF2959D3|Hspell:383935|h[Spark Volley]|h|r. \n\nUpon reaching $389726s1% remaining health, Irideus will become desperate and |cFF2959D3|Hspell:389056|h[Siphon Power]|h|r directly from the facility itself."},
			{id=25384,title="Damage Dealers",body="$bullet;Nullification Devices emit a |cFF2959D3|Hspell:389446|h[Nullifying Pulse]|h|r when they are slain.\n$bullet;Applications of |cFF2959D3|Hspell:383840|h[Ablative Barrier]|h|r are dissipated when struck by |cFF2959D3|Hspell:389446|h[Nullifying Pulse]|h|r.\n$bullet;|cFF2959D3|Hspell:389179|h[Power Overload]|h|r leaves behind a deadly |cFF2959D3|Hspell:389181|h[Power Field]|h|r when it is removed."},
			{id=25385,title="Healers",body="$bullet;|cFF2959D3|Hspell:389056|h[Siphon Power]|h|r will increase the damage from |cFF2959D3|Hspell:389179|h[Power Overload]|h|r and |cFF2959D3|Hspell:389181|h[Power Field]|h|r.\n$bullet;|cFF2959D3|Hspell:389443|h[Purifying Blast]|h|r can do large amounts of damage with a high amount of applications."},
			{id=25386,title="Tanks",body="$bullet;Nullification Devices emit a |cFF2959D3|Hspell:389446|h[Nullifying Pulse]|h|r when they are slain.\n$bullet;Applications of |cFF2959D3|Hspell:383840|h[Ablative Barrier]|h|r are dissipated when struck by |cFF2959D3|Hspell:389446|h[Nullifying Pulse]|h|r."},
			{id=25745,title="Stage One: A Chance at Redemption"},
