			{id=25757,title="Section 14"},
			{id=25394,title="Section 9"},
			{id=25395,title="Section 8"},
			{id=25389,title="Section 5"},
			{id=25744,title="Stage Two: Watcher's Last Stand"},
			{id=25390,title="Section 5",body="$[!23\n\nOn Mythic difficulty, removing an application of Ablative Barrier triggers a blast of Reactive Sparks.$]\n$[!8\nOn Mythic difficulty, removing an application of Ablative Barrier triggers a blast of Reactive Sparks.$]"},
			{id=25775,title="Section 19",difficultyIDs={8,23}},
			{id=29880,title="Section 12",body="$[!23\n\nOn Mythic difficulty, Siphon Power also increases the radius of Power Fields.$]\n$[!8\nOn Mythic difficulty, Siphon Power also increases the radius of Power Fields.$]",difficultyIDs={2,8,23,24}},
