	[2505]={
		encounterID=2505,
		instanceID=1203,
		order=2,
		name="Azureblade",
		lore="As security for the Vault, Azureblade refused to leave when it was sealed, choosing duty over safety. When the blue dragons failed to return, her bitter resignation drove her to eventual madness. Extending her own life with the magics she was sworn to protect, Azureblade now claims ownership over all the blue dragonflight left behind.",
		dungeonEncounterID=2585,
		uiMapID=2075,
		pin={x=0.7604,y=0.5528},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={186739},
		displayIDs={106829,107094,109379},
		loot={
			{itemID=193629,diffs={},faction=-1},
