			{itemID=193632,diffs={},faction=-1},
			{itemID=212685,diffs={},faction=-1},
		},
		sections={
			{id=25405,title="Overview",body="Azureblade assaults the player with various arcane magics and illusions. She conjures Draconic Illusions to protect herself during |cFF2959D3|Hspell:384132 |h[Overwhelming Energy]|h|r."},
			{id=25408,title="Damage Dealers",body="$bullet; Azureblade continues to inflict damage to all players with |cFF2959D3|Hspell:384132 |h[Overwhelming Energy]|h|r until Draconic Illusions are destroyed.\n$bullet; |cFF2959D3|Hspell:385578 |h[Ancient Orb]|h|r inflicts high damage to players in front of Azureblade."},
			{id=25407,title="Healers",body="$bullet; Azureblade continues to inflict damage to all players with |cFF2959D3|Hspell:384132 |h[Overwhelming Energy]|h|r until Draconic Illusions are destroyed.\n$bullet; |cFF2959D3|Hspell:385578 |h[Ancient Orb]|h|r inflicts high damage to players in front of Azureblade."},
			{id=25406,title="Tanks",body="$bullet; |cFF2959D3|Hspell:372222 |h[Arcane Cleave]|h|r inflicts high damage to players in a cone in front of Azureblade.\n$bullet; Azureblade continues to inflict damage to all players with |cFF2959D3|Hspell:384132 |h[Overwhelming Energy]|h|r until Draconic Illusions are destroyed."},
			{id=25515,title="Section 10"},
			{id=25516,title="Draconic Illusion"},
