	[2506]={
		encounterID=2506,
		instanceID=1205,
		order=1,
		name="Basrikron, The Shale Wing",
		lore="Basrikron is significantly heavier than his kin, and as such prefers life on the ground to soaring through the air. Basrikron's surroundings are his to conquer, and allow him to perfect his craft. He speaks and the ground obeys, allowing him to bring to bear the full might of the earth upon those foolish enough to face him.",
		dungeonEncounterID=2640,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={193535},
		displayIDs={106523,108210},
		loot={
			{itemID=200740,diffs={},faction=-1},
			{itemID=200739,diffs={},faction=-1},
			{itemID=200762,diffs={},faction=-1},
			{itemID=200742,diffs={},faction=-1},
			{itemID=200736,diffs={},faction=-1},
		},
		sections={
			{id=25422,title="Overview",body="Basrikron shapes the earth around him with |cFF2959D3|Hspell:385270|h[Fracturing Spires]|h|r, and |cFF2959D3|Hspell:385506|h[Awaken Crag]|h|r. At 100 energy, Basrikron will take flight, and plummet with a |cFF2959D3|Hspell:386259|h[Sundering Crash]|h|r, destroying all |cFF2959D3|Hspell:385879|h[Fractured Spires]|h|r, and any living  |cFF2959D3|Hspell:385506|h[Awaken Crags]|h|r."},
			{id=25423,title="Healers",body="$bullet; |cFF2959D3|Hspell:386259|h[Sundering Crash]|h|r will detonate all |cFF2959D3|Hspell:385879|h[Fractured Spires]|h|r and |cFF2959D3|Hspell:385506|h[Awaken Crags]|h|r, damaging and knocking nearby players into the air.\n$bullet; |cFF2959D3|Hspell:385137|h[Shale Breath]|h|r inflicts heavy Physical damage to its target and increases damage taken.\n$bullet; |cFF2959D3|Hspell:386259|h[Sundering Crash]|h|r inflicts damage to all players."},
			{id=25424,title="Tanks",body="$bullet; |cFF2959D3|Hspell:386259|h[Sundering Crash]|h|r will detonate all |cFF2959D3|Hspell:385879|h[Fractured Spires]|h|r and |cFF2959D3|Hspell:385506|h[Awaken Crags]|h|r, damaging and knocking nearby players into the air.\n$bullet;|cFF2959D3|Hspell:385137|h[Shale Breath]|h|r increases Physical damage taken.\n$bullet;|cFF2959D3|Hspell:385879|h[Fractured Spires]|h|r slow and damage all players near them."},
			{id=25425,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:386259|h[Sundering Crash]|h|r will detonate all |cFF2959D3|Hspell:385879|h[Fractured Spires]|h|r and |cFF2959D3|Hspell:385506|h[Awaken Crags]|h|r, damaging and knocking nearby players into the air.\n$bullet; |cFF2959D3|Hspell:385506|h[Awaken Crag]|h|r summons elementals to attack players."},
			{id=25562,title="Section 5"},
			{id=25599,title="Section 12"},
			{id=25563,title="Section 6"},
