	[2507]={
		encounterID=2507,
		instanceID=1204,
		order=2,
		name="Gulping Goliath",
		lore="Deep within the caverns of the Halls of Infusion lurks the Gulping Goliath. Sire to countless generations of hornswogs, the Goliath and his brood have thrived upon the unprocessed waters of the wellspring. Driven by an insatiable hunger, he will eagerly devour any creature that strays too close to his lair.",
		dungeonEncounterID=2616,
		uiMapID=2083,
		pin={x=0.5402,y=0.8574},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189722},
		displayIDs={102560,103584},
		loot={
			{itemID=193760,diffs={},faction=-1},
			{itemID=193725,diffs={},faction=-1},
			{itemID=193729,diffs={},faction=-1},
