		instanceID=1203,
		order=4,
		name="Umbrelskul",
		lore="Millenia ago, Umbrelskul unwittingly meddled with raw arcane power. Riddled with crystalline growths, he was taken to the Azure Vault until a cure could be found. Sadly, the Vault was sealed away before the research was completed, leaving Umbrelskul sleeping in stasis... until now.",
		dungeonEncounterID=2584,
		uiMapID=2077,
