	[2509]={
		encounterID=2509,
		instanceID=1201,
		order=1,
		name="Vexamus",
		lore="As one of the most tenured professors in the academy, Maxdormu uses his powers as a bronze dragon to help bring his history lessons to life. \n\nWhile this proves to be quite an educational and fun experience, it can occasionally go awry. Vexamus is one of Professor Maxdormu's favorite lessons, but if any historical detail is inaccurate he will be quick to scold any rowdy students.",
		dungeonEncounterID=2562,
		uiMapID=2097,
		pin={x=0.3036,y=0.3574},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189668,194181,195416},
		displayIDs={107525},
		loot={
			{itemID=193710,diffs={},faction=-1},
			{itemID=193708,diffs={},faction=-1},
			{itemID=193709,diffs={},faction=-1},
			{itemID=193711,diffs={},faction=-1},
			{itemID=258529,diffs={2,23},faction=-1},
		},
		sections={
			{id=25504,title="Overview",body="Professor Maxdormu conjures a lesson that recalls the story of Vexamus, introducing the elemental's arsenal of Arcane abilities as the narrative progresses. The professor's magic book summons |cFF2959D3|Hspell:387691|h[Arcane Orbs]|h|r that gravitate towards Vexamus and grant it more power if not intercepted."},
			{id=25505,title="Tanks",body="$bullet;|cFF2959D3|Hspell:385958|h[Arcane Expulsion]|h|r inflicts heavy damage in a frontal cone.\n$bullet;Vexamus gains energy from absorbing |cFF2959D3|Hspell:387691|h[Arcane Orbs]|h|r."},
			{id=25506,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:386173|h[Mana Bombs]|h|r leave behind a pool of |cFF2959D3|Hspell:386201|h[Corrupted Mana]|h|r after detonating.\n$bullet;Vexamus gains energy from absorbing |cFF2959D3|Hspell:387691|h[Arcane Orbs]|h|r."},
			{id=25507,title="Healers",body="$bullet;|cFF2959D3|Hspell:386173|h[Mana Bombs]|h|r leave behind a pool of |cFF2959D3|Hspell:386201|h[Corrupted Mana]|h|r after detonating.\n$bullet;Vexamus gains energy from absorbing |cFF2959D3|Hspell:387691|h[Arcane Orbs]|h|r."},
			{id=25622,title="Professor Maxdormu"},
