	[2510]={
		encounterID=2510,
		instanceID=1204,
		order=3,
		name="Khajin the Unyielding",
		lore="Khajin the Unyielding seethes with hatred for Keeper Tyr for tampering with the ancient wellspring beneath Tyrhold. Waters that once flowed with the eternal essence of Azeroth have been polluted by Order magic. Khajin would see the world freed from the malignant legacy of the titans... at any cost.",
		dungeonEncounterID=2617,
		uiMapID=2083,
		pin={x=0.3112,y=0.8173},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189727},
		displayIDs={107064},
		loot={
			{itemID=193731,diffs={},faction=-1},
			{itemID=193733,diffs={},faction=-1},
			{itemID=193735,diffs={},faction=-1},
			{itemID=193734,diffs={},faction=-1},
			{itemID=212683,diffs={},faction=-1},
		},
		sections={
			{id=25518,title="Overview",body="Khajin the Unyielding assaults her foes with the power of ice and cold. She will alternate between creating Ice Boulders using |cFF2959D3|Hspell:386562|h[Glacial Surge]|h|r and destroying weakened ones using |cFF2959D3|Hspell:386757|h[Hailstorm]|h|r."},
			{id=25519,title="Tanks",body="$bullet;|cFF2959D3|Hspell:386757|h[Hailstorm]|h|r will strike every |cFF2959D3|Hspell:386222|h[Ice Boulder]|h|r.\n$bullet;Damaged |cFF2959D3|Hspell:386222|h[Ice Boulders]|h|r immediately erupt in an |cFF2959D3|Hspell:386295|h[Avalanche]|h|r after being struck a second time."},
			{id=25520,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:386757|h[Hailstorm]|h|r will strike every |cFF2959D3|Hspell:386222|h[Ice Boulder]|h|r, not just those being used for cover.\n$bullet;Damaged |cFF2959D3|Hspell:386222|h[Ice Boulders]|h|r immediately erupt in an |cFF2959D3|Hspell:386295|h[Avalanche]|h|r after being struck a second time."},
			{id=25521,title="Healers",body="$bullet;|cFF2959D3|Hspell:386757|h[Hailstorm]|h|r will strike every |cFF2959D3|Hspell:386222|h[Ice Boulder]|h|r, not just those being used for cover.\n$bullet;Damaged |cFF2959D3|Hspell:386222|h[Ice Boulders]|h|r immediately erupt in an |cFF2959D3|Hspell:386295|h[Avalanche]|h|r after being struck a second time.\n$bullet;Dispel |cFF2959D3|Hspell:385963|h[Frost Shock]|h|r quickly so your ally can escape harmful area damage."},
			{id=25788,title="Section 11",difficultyIDs={2,8,23,24}},
			{id=29890,title="Section 12",difficultyIDs={1}},
			{id=25575,title="Section 9",difficultyIDs={2,8,23,24}},
