	[2511]={
		encounterID=2511,
		instanceID=1204,
		order=4,
		name="Primal Tsunami",
		lore="Infuser Sariya is driven to restore the world to what it once was: a primal elemental landscape of unfettered power. She has used all her will and cunning to summon the Primal Tsunami, an elemental being mighty enough to topple Keeper Tyr's facility and return the waters of the wellspring to their natural state.",
		dungeonEncounterID=2618,
		uiMapID=2083,
		pin={x=0.429,y=0.4759},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={189729,191516},
		displayIDs={102900,106934},
		loot={
			{itemID=193738,diffs={},faction=-1},
			{itemID=193742,diffs={},faction=-1},
			{itemID=193739,diffs={},faction=-1},
			{itemID=193740,diffs={},faction=-1},
			{itemID=193741,diffs={},faction=-1},
			{itemID=198059,diffs={23},faction=-1},
			{itemID=198056,diffs={1},faction=-1},
			{itemID=198058,diffs={2},faction=-1},
			{itemID=212682,diffs={},faction=-1},
			{itemID=196975,diffs={24},faction=-1},
			{itemID=197007,diffs={24},faction=-1},
		},
		sections={
			{id=25525,title="Overview",body="The Primal Tsunami attempts to drown its enemies in the now Primalist infused waters in the depths of the Halls of Infusion. It forms |cFF2959D3|Hspell:387363|h[Infused Globules]|h|r, and then displaces its enemies into danger.\n\nUpon reaching 50% health, the Tsunami uses |cFF2959D3|Hspell:388420|h[Cast Away]|h|r on its foes and submerges. While submerged, the Tsunami's Primalist allies jump to action, infusing it with more energy."},
			{id=25526,title="Tanks",body="$bullet;|cFF2959D3|Hspell:387363|h[Infused Globules]|h|r inflict |cFF2959D3|Hspell:387359|h[Waterlogged]|h|r on players they come into contact with.\n$bullet;The Primal Tsunami will continue to use |cFF2959D3|Hspell:389872|h[Undertow]|h|r if there are no players within melee range of it."},
			{id=25527,title="Damage Dealers",body="$bullet;Primalist Infusers will continue to |cFF2959D3|Hspell:387619|h[Infuse]|h|r the Primal Tsunami until they are interrupted.\n$bullet;|cFF2959D3|Hspell:383204|h[Crashing Tsunami]|h|r will knock back and slow players during |cFF2959D3|Hspell:388420|h[Cast Away]|h|r."},
			{id=25528,title="Healers",body="$bullet;|cFF2959D3|Hspell:387571|h[Focused Deluge]|h|r will inflict high Frost damage to the target.\n$bullet;|cFF2959D3|Hspell:383204|h[Crashing Tsunami]|h|r will knock back and slow players during |cFF2959D3|Hspell:388420|h[Cast Away]|h|r."},
			{id=25529,title="Stage One: Violent Swells"},
