	[2512]={
		encounterID=2512,
		instanceID=1201,
		order=2,
		name="Overgrown Ancient",
		lore="Professors Mystakria and Ichistrasz have used just a touch too much magic in an effort to clear the botany labs. Now they have a big, leafy problem on their hands in the form of an Overgrown Ancient that threatens to undo all their hard work.",
		dungeonEncounterID=2563,
		uiMapID=2097,
		pin={x=0.5633,y=0.4177},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={196482},
		displayIDs={104474,107359,109194},
		loot={
			{itemID=193713,diffs={},faction=-1},
			{itemID=193715,diffs={},faction=-1},
			{itemID=193716,diffs={},faction=-1},
			{itemID=193712,diffs={},faction=-1},
			{itemID=193717,diffs={},faction=-1},
			{itemID=193714,diffs={},faction=-1},
		},
		sections={
			{id=25532,title="Overview",body="The Overgrown Ancient attempts to crush the tank with |cFF2959D3|Hspell:388544|h[Barkbreaker]|h|r and repeatedly forces waves of dormant lashers to grow with |cFF2959D3|Hspell:388796|h[Germinate]|h|r.\n\nUpon reaching 100 energy, the Overgrown Ancient uses |cFF2959D3|Hspell:388923|h[Burst Forth]|h|r to awaken all dormant lashers that have not yet been killed, causing them to attack players."},
			{id=25533,title="Tanks",body="$bullet;Being hit by |cFF2959D3|Hspell:388544|h[Barkbreaker]|h|r greatly increases Physical damage taken for a short time after.\n$bullet;Once awakened by |cFF2959D3|Hspell:388923|h[Burst Forth]|h|r, Hungry Lashers can inflict significant damage if left unchecked.\n$bullet;Ancient Branches cast |cFF2959D3|Hspell:396640|h[Healing Touch]|h|r, which can be interrupted."},
			{id=25534,title="Damage Dealers",body="$bullet;Hungry Lashers can be damaged and killed even before the Ancient awakens them with |cFF2959D3|Hspell:388923|h[Burst Forth]|h|r.\n$bullet;Ancient Branches cast |cFF2959D3|Hspell:396640|h[Healing Touch]|h|r, which can be interrupted."},
			{id=25535,title="Healers",body="$bullet;The target of |cFF2959D3|Hspell:388544|h[Barkbreaker]|h|r takes greatly increased Physical damage for a short time after being hit.\n$bullet;|cFF2959D3|Hspell:388923|h[Burst Forth]|h|r inflicts significant damage to all party members."},
			{id=25729,title="Section 11"},
			{id=25730,title="Hungry Lasher"},
			{id=25732,title="Section 12",difficultyIDs={8,23}},
			{id=25731,title="Section 13"},
			{id=25687,title="Section 8",difficultyIDs={2,8,23,24}},
			{id=26067,title="Section 13",difficultyIDs={8,23}},
			{id=25688,title="Ancient Branch"},
			{id=25710,title="Section 10"},
			{id=26069,title="Section 14",difficultyIDs={8,23}},
			{id=25669,title="Section 8"},
		},
	},
	[2514]={
		encounterID=2514,
		instanceID=1201,
		order=5,
		name="Echo of Doragosa",
		lore="Headteacher Doragosa thought of everything when it came to Algeth'ar Academy. Including a complex simulacrum of herself to take care of any day to day tasks and upkeep while the Isles lay dormant. Now that the Academy is open once again, perhaps she can use it to help keep track of all the new students. It's done a fine job in the interim, and is absolutely the one spell that did not degrade after all these years. Perfectly stable and helpful. Right?",
		dungeonEncounterID=2565,
		uiMapID=2099,
		pin={x=0.6177,y=0.6062},
		difficultyIDs={1,2,8,23,24,205},
		npcIDs={190609},
