			{itemID=198910,diffs={24},faction=-1},
		},
		sections={
			{id=25653,title="Overview",body="The Echo of Doragosa assaults her enemies with powerful Arcane attacks, applying |cFF2959D3|Hspell:389011|h[Overwhelming Power]|h|r and creating |cFF2959D3|Hspell:388901|h[Arcane Rifts]|h|r."},
			{id=25654,title="Tanks",body="$bullet; Multiple applications of |cFF2959D3|Hspell:389011|h[Overwhelming Power]|h|r will create |cFF2959D3|Hspell:388901|h[Arcane Rifts]|h|r.\n$bullet; |cFF2959D3|Hspell:1282251|h[Astral Blast]|h|r inflicts heavy arcane damage and applies an application of |cFF2959D3|Hspell:389011|h[Overwhelming Power]|h|r."},
			{id=25655,title="Healers",body="$bullet; Multiple applications of |cFF2959D3|Hspell:389011|h[Overwhelming Power]|h|r will create |cFF2959D3|Hspell:388901|h[Arcane Rifts]|h|r."},
			{id=25656,title="Damage Dealers",body="$bullet; Multiple applications of |cFF2959D3|Hspell:389011|h[Overwhelming Power]|h|r will create |cFF2959D3|Hspell:388901|h[Arcane Rifts]|h|r.\n$bullet;"},
