	[2515]={
		encounterID=2515,
		instanceID=1205,
		order=0,
		name="Strunraan, The Sky's Misery",
		lore="Strunraan's presence has been known to make the skies cry. His tempest electrifies the air and wreaks havoc upon the land. Drawn to the gale power, Strunraan now threatens the lands and people of the Ohn'ahran Plains.",
		dungeonEncounterID=2651,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={193534},
		displayIDs={108212},
		loot={
			{itemID=200687,diffs={},faction=-1},
			{itemID=200676,diffs={},faction=-1},
			{itemID=200734,diffs={},faction=-1},
			{itemID=200688,diffs={},faction=-1},
			{itemID=200733,diffs={},faction=-1},
		},
		sections={
			{id=25670,title="Overview",body="Strunraan's gale mastery keeps any threat away with |cFF2959D3|Hspell:385980|h[Thunder Vortex]|h|r and |cFF2959D3|Hspell:390295|h[Arc Expulsion]|h|r. With his electrifying presence, enemies struck by his powers gain |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r. At 100 energy, Strunraan will take flight and cause |cFF2959D3|Hspell:387191|h[Empowered Storm]|h|r."},
			{id=25671,title="Healers",body="$bullet; |cFF2959D3|Hspell:387191|h[Empowered Storm]|h|r can cause heavy Nature damage.\n$bullet; Strunraan will knock players away with |cFF2959D3|Hspell:385980|h[Thunder Vortex]|h|r and |cFF2959D3|Hspell:390295|h[Arc Expulsion]|h|r.\n$bullet; |cFF2959D3|Hspell:387265|h[Overcharge]|h|r and |cFF2959D3|Hspell:388980|h[Storm's Strike]|h|r inflict heavy Nature damage to nearby players."},
			{id=25672,title="Tanks",body="$bullet; Strunraan's storm-based abilities imbue the inflicted target with |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r.\n$bullet; |cFF2959D3|Hspell:387216|h[Shock Water]|h|r inflicts heavy damage to all players standing in the water with Strunraan.\n$bullet; |cFF2959D3|Hspell:390295|h[Arc Expulsion]|h|r inflicts Nature damage to players standing directly in front of Strunraan."},
			{id=25673,title="Damage Dealers",body="$bullet; Strunraan's storm-based abilities imbue the inflicted target with |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r.\n$bullet; Strunraan will knock players away with |cFF2959D3|Hspell:385980|h[Thunder Vortex]|h|r and |cFF2959D3|Hspell:390295|h[Arc Expulsion]|h|r.\n$bullet; |cFF2959D3|Hspell:387265|h[Overcharge]|h|r inflicts heavy Nature damage to nearby players."},
			{id=25674,title="Surrounding Storm"},
			{id=25728,title="Section 11"},
			{id=25708,title="Section 10"},
			{id=25675,title="Section 5"},
			{id=25676,title="Section 8"},
			{id=25677,title="Section 9"},
