	[2517]={
		encounterID=2517,
		instanceID=1205,
		order=1,
		name="Bazual, The Dreaded Flame",
		lore="Bazual's special connection to the Plane of Fire allows him to directly siphon power from the Firelands. With the help of the Primalist forces, Bazual is expanding portals to the Firelands in the Azure Span.",
		dungeonEncounterID=2653,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={193532},
		displayIDs={108209},
		loot={
			{itemID=200661,diffs={},faction=-1},
			{itemID=200663,diffs={},faction=-1},
			{itemID=200654,diffs={},faction=-1},
			{itemID=200660,diffs={},faction=-1},
			{itemID=200761,diffs={},faction=-1},
		},
		sections={
			{id=25864,title="Overview",body="Bazual will blast players with |cFF2959D3|Hspell:389725|h[Magma Eruption]|h|r, leaving behind a pool of molten magma. At 100 energy, Bazual will take to the sky and cast |cFF2959D3|Hspell:389431|h[Deterring Flame]|h|r to set all players ablaze and knocking them back.\n\n\nAt 40% Health, Bazual will empower himself with flames from the Firelands through |cFF2959D3|Hspell:391247|h[Flame Infusion]|h|r, damaging all players with |cFF2959D3|Hspell:391257|h[Searing Heat]|h|r. While infused, Bazual will cast |cFF2959D3|Hspell:390635|h[Rain of Destruction]|h|r at 100 energy instead."},
			{id=25865,title="Tanks",body="$bullet;|cFF2959D3|Hspell:389514|h[Lava Breath]|h|r inflicts heavy damage to all players caught in it.\n\n$bullet;|cFF2959D3|Hspell:389725|h[Magma Eruption]|h|r leaves behind a pool of magma that will inflict Fire damage to nearby players."},
			{id=25866,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:389431|h[Deterring Flame]|h|r will inflict Fire damage to all players and knocking them back.\n\n$bullet;|cFF2959D3|Hspell:389725|h[Magma Eruption]|h|r leaves behind a pool of magma that will inflict Fire damage to nearby players.\n\n$bullet;While infused, Bazual will cast |cFF2959D3|Hspell:390635|h[Rain of Destruction]|h|r at 100 energy."},
			{id=25867,title="Healers",body="$bullet;|cFF2959D3|Hspell:389431|h[Deterring Flame]|h|r will inflict Fire damage to all players and knocking them back.\n\n$bullet;While infused, Bazual's |cFF2959D3|Hspell:391257|h[Searing Heat]|h|r will inflict Fire damage on all players every 2 sec.\n\n$bullet;While infused, Bazual will cast |cFF2959D3|Hspell:390635|h[Rain of Destruction]|h|r at 100 energy."},
			{id=25874,title="Phase One"},
			{id=25875,title="Section 7"},
