	[2518]={
		encounterID=2518,
		instanceID=1205,
		order=1,
		name="Liskanoth, The Futurebane",
		lore="Imbued with an immense icy power, Liskanoth oversees the land conquered by the Primalists. Liskanoth's very presence casts a chill down the spine of all who encounter her. If left to continue her conquest, Liskanoth will annihilate all who dare enter Thaldraszus.",
		dungeonEncounterID=2652,
		pin={x=0.5,y=0.5},
