		sections={
			{id=25884,title="Overview",body="Liskanoth harnesses her power to confine players with |cFF2959D3|Hspell:389287|h[Glacial Storm]|h|r and |cFF2959D3|Hspell:388767|h[Binding Ice]|h|r. Upon reaching 100 energy, Liskanoth ascends to the skies and sweeps the valley, unleashing a powerful |cFF2959D3|Hspell:389762|h[Deep Freeze]|h|r on players below."},
			{id=25885,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:388767|h[Binding Ice]|h|r roots targets in place until they are defeated.\n$bullet;|cFF2959D3|Hspell:389287|h[Glacial Storm]|h|r leaves behind frozen patches of ground that reduce players' movement speed.\n$bullet;|cFF2959D3|Hspell:389762|h[Deep Freeze]|h|r inflicts heavy damage to all in Liskanoth's path and leaves them frozen."},
			{id=25886,title="Healers",body="$bullet;|cFF2959D3|Hspell:389287|h[Glacial Storm]|h|r leaves behind frozen patches of ground that reduce players' movement speed.\n$bullet;|cFF2959D3|Hspell:389762|h[Deep Freeze]|h|r inflicts heavy damage to all in Liskanoth's path and leaves them frozen."},
			{id=25887,title="Tanks",body="$bullet;|cFF2959D3|Hspell:388925|h[Chilling Breath]|h|r inflicts heavy damage and applies |cFF2959D3|Hspell:388924|h[Biting Frost]|h|r to all hit\n$bullet;|cFF2959D3|Hspell:389287|h[Glacial Storm]|h|r leaves behind frozen patches of ground that reduce players' movement speed.\n$bullet;|cFF2959D3|Hspell:389762|h[Deep Freeze]|h|r inflicts heavy damage to all in Liskanoth's path and leaves them frozen."},
