	[2520]={
		encounterID=2520,
		instanceID=1208,
		order=9,
		name="Scalecommander Sarkareth",
		lore="As leader of the Sundered Flame, Scalecommander Sarkareth broke away from the rest of the dracthyr to forge a new future. He has since led his forces to Aberrus, intent on claiming the legacy he believes rightfully belongs to his kind and willing to do anything to obtain it.",
		dungeonEncounterID=2685,
		uiMapID=2170,
		pin={x=0.4901,y=0.7125},
		difficultyIDs={14,15,16,17,220},
