	[2521]={
		encounterID=2521,
		instanceID=1209,
		order=1,
		name="Chronikar",
		lore="Chronikar spent her entire life in service to the infinite dragonflight, making her way up the ranks until she earned the title of commander. Even among the radical infinites, her zealotry is unmatched. As the venerated rearguard, she will stop at nothing to put an end to any who dare oppose her order.",
		dungeonEncounterID=2666,
		uiMapID=2190,
		pin={x=0.5769,y=0.6612},
		difficultyIDs={2,8,23,216},
		npcIDs={198995},
		displayIDs={111556},
		loot={
			{itemID=207828,diffs={},faction=-1},
			{itemID=207838,diffs={},faction=-1},
			{itemID=207991,diffs={},faction=-1},
			{itemID=207995,diffs={},faction=-1},
			{itemID=207819,diffs={},faction=-1},
			{itemID=207923,diffs={},faction=-1},
		},
		sections={
			{id=26415,title="Overview",body="Chronikar stomps, forming |cFF2959D3|Hspell:401794|h[Withering Sandpools]|h|r that deny ground. Additionally, she uses her time-bending axe to strike with |cFF2959D3|Hspell:413013|h[Chronoshear]|h|r. At 100 energy, she leaps at players with |cFF2959D3|Hspell:413105|h[Eon Shatter]|h|r, unleashing fragments of timespace."},
			{id=27220,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:403486|h[Eon Residue]|h|r causes |cFF2959D3|Hspell:417480|h[Residue Blast]|h|r if it fails to hit a player.\n$bullet; |cFF2959D3|Hspell:413105|h[Eon Shatter]|h|r and the resulting |cFF2959D3|Hspell:405970|h[Eon Fragments]|h|r inflict significant damage.",difficultyIDs={8,23}},
			{id=26412,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:401794|h[Withering Sandpools]|h|r inflict damage upon forming and then deny ground.\n$bullet; |cFF2959D3|Hspell:413105|h[Eon Shatter]|h|r and the resulting |cFF2959D3|Hspell:405970|h[Eon Fragments]|h|r inflict significant damage.",difficultyIDs={2}},
			{id=27221,title="Healers",body="$bullet; |cFF2959D3|Hspell:413013|h[Chronoshear]|h|r's healing absorption prevents dispelling of |cFF2959D3|Hspell:413041|h[Sheared Lifespan]|h|r.\n$bullet; |cFF2959D3|Hspell:403486|h[Eon Residue]|h|r causes |cFF2959D3|Hspell:417480|h[Residue Blast]|h|r if it fails to hit a player.",difficultyIDs={8,23}},
			{id=26413,title="Healers",body="$bullet; |cFF2959D3|Hspell:413013|h[Chronoshear]|h|r inflicts high damage and absorbs healing.\n$bullet; |cFF2959D3|Hspell:401794|h[Withering Sandpools]|h|r inflict damage upon forming and then deny ground.",difficultyIDs={2}},
