	[2522]={
		encounterID=2522,
		instanceID=1208,
		order=1,
		name="Kazzara, the Hellforged",
		lore="Although Neltharion would not use them himself until much later, he experimented with elementium plating in the early days of Aberrus. The end result of elementium and shadowflame was Kazzara, who was deemed far too unstable for release. Driven mad by the excruciating pain of her elementium plates, she now serves as the guardian of the Shadowed Crucible.",
		dungeonEncounterID=2688,
		uiMapID=2166,
		pin={x=0.5132,y=0.7224},
		difficultyIDs={14,15,16,17,220},
		npcIDs={201261,205674},
		displayIDs={111505},
		loot={
