	[2525]={
		encounterID=2525,
		instanceID=1208,
		order=5,
		name="Rashok, the Elder",
		lore="Imprisoned within Aberrus for a millennia, the Zaqali elder Rashok has been perpetually drained of the raging flame within him to power Neltharion's twisted laboratory. Existing on the edge of death for so long has driven the elder mad. Should he break free, his vengeance will scour the Shadowed Crucible's halls.",
