	[2526]={
		encounterID=2526,
		instanceID=1209,
		order=5,
		name="Tyr, the Infinite Keeper",
		lore="With the true timeline now altered by Murozond's rise, the heroes of Azeroth are faced with many oddities. Chief among them being Titan-Keeper Tyr joining forces with the infinite dragonflight. His legendary loyalty now turned against them, the heroes of Azeroth have no choice but to fight. To win.",
		dungeonEncounterID=2670,
		uiMapID=2195,
		pin={x=0.4211,y=0.4615},
		difficultyIDs={2,8,23,216},
		npcIDs={198998},
		displayIDs={112999},
		loot={
			{itemID=207552,diffs={},faction=-1},
			{itemID=207927,diffs={},faction=-1},
			{itemID=207876,diffs={},faction=-1},
			{itemID=207873,diffs={},faction=-1},
			{itemID=207950,diffs={},faction=-1},
			{itemID=208391,diffs={},faction=-1},
		},
		sections={
			{id=26245,title="Overview",body="Tyr repeatedly assaults players with |cFF2959D3|Hspell:404296|h[Infinite Hand Technique]|h|r, expending his energy in the process.\n\nWhen all of his energy is expended, Tyr siphons additional power from the Infinite Oathstone, shielding himself with |cFF2959D3|Hspell:410249|h[Radiant Barrier]|h|r and triggering |cFF2959D3|Hspell:404315|h[Temporal Essence]|h|r."},
			{id=26246,title="Tanks",body="$bullet;|cFF2959D3|Hspell:401248|h[Titanic Blow]|h|r inflicts heavy damage to players in front of Tyr.\n$bullet;Any |cFF2959D3|Hspell:406543|h[Stolen Time]|h|r that reach the Infinite Oathstone empower Tyr's |cFF2959D3|Hspell:410249|h[Radiant Barrier]|h|r.\n$bullet;|cFF2959D3|Hspell:400641|h[Dividing Strike]|h|r damage is evenly split among players hit."},
			{id=26247,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:406543|h[Stolen Time]|h|r can be collected to increase your haste and movement speed.\n$bullet;Any |cFF2959D3|Hspell:406543|h[Stolen Time]|h|r that reach the Infinite Oathstone empower Tyr's |cFF2959D3|Hspell:410249|h[Radiant Barrier]|h|r.\n$bullet;|cFF2959D3|Hspell:400641|h[Dividing Strike]|h|r damage is evenly split among players hit."},
			{id=26248,title="Healers",body="$bullet;When |cFF2959D3|Hspell:400649|h[Spark of Tyr]|h|r expires, it inflicts heavy damage to all players.\n$bullet;Any |cFF2959D3|Hspell:406543|h[Stolen Time]|h|r that reach the Infinite Oathstone empower Tyr's |cFF2959D3|Hspell:410249|h[Radiant Barrier]|h|r.\n$bullet;|cFF2959D3|Hspell:400641|h[Dividing Strike]|h|r damage is evenly split among players hit."},
			{id=26250,title="Silver Hand Technique"},
			{id=26253,title="Titanic Blow"},
			{id=27373,title="Section 15",difficultyIDs={8,23}},
			{id=26254,title="Dividing Strike"},
			{id=26255,title="Consecrated Ground",difficultyIDs={8,23}},
