		sections={
			{id=26265,title="Overview",body="Magmorax launches |cFF2959D3|Hspell:402989|h[Molten Spittle]|h|r at players' locations that form |cFF2959D3|Hspell:403103|h[Magma Puddles]|h|r on impact. While Magmorax stands within a puddle, he gains |cFF2959D3|Hspell:407879|h[Blazing Tantrum]|h|r.\n\nOver the course of the fight, Magmorax gains molten energy. Upon reaching 100 energy, Magmorax unleashes |cFF2959D3|Hspell:408358|h[Catastrophic Eruption]|h|r, destroying all in his domain."},
			{id=26266,title="Tanks",body="$bullet; Magmorax enters a |cFF2959D3|Hspell:407879|h[Blazing Tantrum]|h|r when within a |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r.\n$bullet; |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r continues to grow over time.\n$bullet; |cFF2959D3|Hspell:401348|h[Incinerating Maws]|h|r inflict heavy damage on his current target and increases the damage taken from subsequent attacks of |cFF2959D3|Hspell:401348|h[Incinerating Maws]|h|r."},
			{id=26267,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:402989|h[Molten Spittle]|h|r creates a |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r at multiple players' locations.\n$bullet; |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r continues to grow over time.\n$bullet; |cFF2959D3|Hspell:413351|h[Lava Ejection]|h|r inflicts massive Fire damage to all players and leaves a |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r behind if it fails to hit at least one player."},
			{id=27104,title="Healers",body="$bullet; |cFF2959D3|Hspell:408839|h[Searing Heat]|h|r inflicts increasing damage to players standing within a |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r.\n$bullet; |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r continues to grow over time.\n$bullet; Magmorax inflicts increasing Fire damage with every |cFF2959D3|Hspell:403740|h[Igniting Roar]|h|r.",difficultyIDs={15,16}},
			{id=26268,title="Healers",body="$bullet; |cFF2959D3|Hspell:410676|h[Searing Heat]|h|r inflicts increasing damage to players standing within a |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r.\n$bullet; |cFF2959D3|Hspell:403103|h[Magma Puddle]|h|r continues to grow over time.\n$bullet; Magmorax inflicts increasing Fire damage with every |cFF2959D3|Hspell:403740|h[Igniting Roar]|h|r.",difficultyIDs={14,17}},
			{id=26546,title="Section 12"},
			{id=26790,title="Section 8",difficultyIDs={14,15,17}},
			{id=26791,title="Section 12",body="$[!16\n\nOn Mythic difficulty, Magma Puddles are unable to be fully absorbed. $]",difficultyIDs={16}},
