	[2528]={
		encounterID=2528,
		instanceID=1209,
		order=2,
		name="Manifested Timeways",
		lore="A manifestation of the sands of time itself. This ancient being is always watching, always waiting for the moment when the Timeways are in peril. She was unable to stop the infinite dragonflight as they crashed their way into the past. Now, faced with more intruders, she refuses to fail a second time.",
		dungeonEncounterID=2667,
		uiMapID=2191,
		pin={x=0.6755,y=0.5858},
		difficultyIDs={2,8,23,216},
		npcIDs={198996},
		displayIDs={113190},
		loot={
			{itemID=207996,diffs={},faction=-1},
			{itemID=207999,diffs={},faction=-1},
			{itemID=207851,diffs={},faction=-1},
			{itemID=207858,diffs={},faction=-1},
			{itemID=207903,diffs={},faction=-1},
			{itemID=207898,diffs={},faction=-1},
			{itemID=207566,diffs={},faction=-1},
		},
		sections={
			{id=26291,title="Overview",body="The Timeways coalesce in response to Nozdormu's intervention. Fields of |cFF2959D3|Hspell:403910|h[Decaying Time]|h|r and |cFF2959D3|Hspell:403912|h[Accelerating Time]|h|r continually tick around the Manifested Timestream, manipulating how their abilities execute."},
			{id=26292,title="Tanks",body="$bullet;|cFF2959D3|Hspell:403910|h[Decaying Time]|h|r and |cFF2959D3|Hspell:403912|h[Accelerating Time]|h|r impactfully manipulate |cFF2959D3|Hspell:405431|h[Fragments of Time]|h|r's travel speed.\n$bullet;Manifested Timeways casts |cFF2959D3|Hspell:414307|h[Radiant]|h|r when there are no valid targets in melee range."},
			{id=26294,title="Healers",body="$bullet;|cFF2959D3|Hspell:404141|h[Chrono-faded]|h|r's released |cFF2959D3|Hspell:405448|h[Chronofade]|h|r travels notably faster when dispelled inside |cFF2959D3|Hspell:403912|h[Accelerating Time]|h|r.\n$bullet;|cFF2959D3|Hspell:403910|h[Decaying Time]|h|r and |cFF2959D3|Hspell:403912|h[Accelerating Time]|h|r impactfully manipulate |cFF2959D3|Hspell:405431|h[Fragments of Time]|h|r's travel speed."},
			{id=26293,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:404141|h[Chrono-faded]|h|r's |cFF2959D3|Hspell:405448|h[Chronofade]|h|r is dangerous when afflicted with |cFF2959D3|Hspell:403910|h[Decaying Time]|h|r.\n$bullet;|cFF2959D3|Hspell:403910|h[Decaying Time]|h|r and |cFF2959D3|Hspell:403912|h[Accelerating Time]|h|r impactfully manipulate |cFF2959D3|Hspell:405431|h[Fragments of Time]|h|r's travel speed."},
			{id=26295,title="Timeways Conflux",body="Shifting fields of time energy surrounds the Manifested Timeways, applying Accelerating Time or Decaying Time."},
