		instanceID=1208,
		order=2,
		name="The Amalgamation Chamber",
		lore="The Eternal Blaze burns with the heat of a thousand suns, while the Essence of Shadow blooms with darkness incarnate. Although exceptionally powerful on their own, when combined they surge with the unchecked might of shadowflame, creating a whirlwind of ultimate destruction.",
		dungeonEncounterID=2687,
		uiMapID=2167,
