		sections={
			{id=26304,title="Overview",body="The Eternal Blaze and The Essense of Shadow pulse with energy, applying |cFF2959D3|Hspell:402617|h[Blazing Heat]|h|r and |cFF2959D3|Hspell:401809|h[Corrupting Shadow]|h|r to nearby players. When either elemental reaches 50% health remaining, the two elementals combine to create The Shadowflame Amalgamation."},
			{id=26305,title="Damage Dealers",body="$bullet; The Eternal Blaze and Essence of Shadow combine their health to form the Shadowflame Amalgamation when one reaches 50% health remaining.\n$bullet; |cFF2959D3|Hspell:401809|h[Corrupting Shadows]|h|r and |cFF2959D3|Hspell:402617|h[Blazing Heat]|h|r are periodically applied to players nearby each elemental."},
			{id=26306,title="Healers",body="$bullet; |cFF2959D3|Hspell:401809|h[Corrupting Shadows]|h|r and |cFF2959D3|Hspell:402617|h[Blazing Heat]|h|r are periodically applied to players nearby each elemental.\n$bullet; |cFF2959D3|Hspell:403748|h[Fiery Meteor]|h|r inflicts massive damage, split among players in the effect.\n$bullet; |cFF2959D3|Hspell:405394|h[Shadowflame Contamination]|h|r inflicts increasing damage until the Shadowflame Amalgamation is defeated."},
			{id=26307,title="Tanks",body="$bullet; |cFF2959D3|Hspell:403699|h[Shadow Spike]|h|r and |cFF2959D3|Hspell:403203|h[Flame Slash]|h|r inflict heavy magic damage.\n$bullet;The combination of |cFF2959D3|Hspell:405914|h[Withering Vulnerability]|h|r and |cFF2959D3|Hspell:406783|h[Shadowflame Burst]|h|r inflicts massive damage.",difficultyIDs={14,17}},
			{id=27124,title="Tanks",body="$bullet; The Eternal Blaze and Essence of Shadow gain |cFF2959D3|Hspell:408095|h[Elemental Instability]|h|r while near each other.\n$bullet; |cFF2959D3|Hspell:403699|h[Shadow Spike]|h|r and |cFF2959D3|Hspell:403203|h[Flame Slash]|h|r inflict heavy magic damage.\n$bullet;The combination of |cFF2959D3|Hspell:405914|h[Withering Vulnerability]|h|r and |cFF2959D3|Hspell:406783|h[Shadowflame Burst]|h|r inflicts massive damage.",difficultyIDs={15,16}},
			{id=26631,title="Stage One: Shadow and Flame"},
			{id=26633,title="Section 42",difficultyIDs={15,16}},
