	[2531]={
		encounterID=2531,
		instanceID=1205,
		order=1,
		name="The Zaqali Elders",
		lore="Vakan and Gholna, powerful djaradin elders, are each a master over their respective element. Gholna with lava and Vakan with shadowflame, they are locked in constant conflict over who is stronger. Through devastation and chaos, each elder attempts to outdo the other until one of them is crowned victor.",
		dungeonEncounterID=2696,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={203219,203220},
		displayIDs={112005,112006},
		loot={
			{itemID=204431,diffs={},faction=-1},
			{itemID=204432,diffs={},faction=-1},
			{itemID=204409,diffs={},faction=-1},
