		sections={
			{id=26369,title="Section 1",body="A master at manipulating the battlefield, Zskarn utilizes several deadly traps to test the capabilities of players. Zskarn creates Dragonfire Golems to aid him by activating nearby |cFF2959D3|Hspell:405462|h[Dragonfire Traps]|h|r to burn players in the vicinity. \n\nZskarn passively generates energy, and upon reaching 100 energy unleashes waves of |cFF2959D3|Hspell:405439|h[Tactical Destruction]|h|r from nearby Dragon Statues to decimate players."},
			{id=26370,title="Tanks",body="$bullet; |cFF2959D3|Hspell:406202|h[Tactical Destruction]|h|r unleashes multiple waves of Dragonfire from nearby dragon statues that are lethal to players caught within.\n$bullet; |cFF2959D3|Hspell:404942|h[Searing Claws]|h|r inflicts increasing Fire damage to Zskarn's current target with each swing.\n$bullet; |cFF2959D3|Hspell:404955|h[Shrapnel Bomb]|h|r inflicts massive Physical damage to all players if not dealt with in time."},
			{id=26371,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:406202|h[Tactical Destruction]|h|r unleashes multiple waves of Dragonfire from nearby dragon statues that are lethal to players caught within.\n$bullet; |cFF2959D3|Hspell:403978|h[Blast Wave]|h|r inflicts heavy Fire damage and knocks players back.\n$bullet; Dragonfire Golems attempt to activate additional |cFF2959D3|Hspell:405462|h[Dragonfire Traps]|h|r."},
			{id=26372,title="Healers",body="$bullet; |cFF2959D3|Hspell:406202|h[Tactical Destruction]|h|r unleashes multiple waves of Dragonfire from nearby dragon statues that are lethal to players caught within.\n$bullet; |cFF2959D3|Hspell:403978|h[Blast Wave]|h|r inflicts heavy Fire damage and knocks players back.\n$bullet; |cFF2959D3|Hspell:404007|h[Unstable Embers]|h|r inflicts high damage to several players and causes them to damage nearby allies."},
			{id=26373,title="Section 5",difficultyIDs={14,17}},
			{id=27103,title="Section 17",difficultyIDs={15,16}},
			{id=26394,title="Section 7"},
