		sections={
			{id=26510,title="Overview",body="Grommash Hellscream commands the Forces of the Horde in an infinite battle against the Forces of the Alliance. With Gorehowl in hand, Grommash cleaves his foes, rallies his troops, and exercises skill at slaying enemies."},
			{id=26511,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:418046|h[FOR THE HORDE!]|h|r brings additional enemy combatants against players.\n$bullet;|cFF2959D3|Hspell:410234|h[Bladestorm]|h|r pursues a marked player, inflicting damage in a nearby radius.\n$bullet;|cFF2959D3|Hspell:408228|h[Shockwave]|h|r casts three times in rapid succession."},
			{id=26512,title="Healers",body="$bullet;|cFF2959D3|Hspell:418046|h[FOR THE HORDE!]|h|r brings additional enemy combatants against players.\n$bullet;|cFF2959D3|Hspell:410234|h[Bladestorm]|h|r pursues a marked player, inflicting damage in a nearby radius.\n$bullet;|cFF2959D3|Hspell:408228|h[Shockwave]|h|r casts three times in rapid succession."},
			{id=26513,title="Tanks",body="$bullet;|cFF2959D3|Hspell:410254|h[Decapitate]|h|r strikes twice, applying |cFF2959D3|Hspell:410497|h[Mortal Wounds]|h|r on each swing.\n$bullet;|cFF2959D3|Hspell:418046|h[FOR THE HORDE!]|h|r brings additional enemy combatants against players.\n$bullet;|cFF2959D3|Hspell:408228|h[Shockwave]|h|r casts three times in rapid succession."},
			{id=26514,title="The Infinite Battlefield",body="This Time-Lost Battlefield rages on. Forces of the Horde and Alliance do battle, endlessly entering the arena."},
			{id=26515,title="Forces of the Horde"},
			{id=27206,title="Horde Grunt",body="This basic warrior of the Horde is equipped with a mighty axe and battle-worn armor."},
