	[2535]={
		encounterID=2535,
		instanceID=1209,
		order=3,
		name="Blight of Galakrond",
		lore="These primal dragons were brought back by the necrotic energies dripping from the corpse of Galakrond. Ahnzon is the crackling hunger of the storm. Dazhak the all-consuming gluttony of the flame. Loszkeleth the seeping starvation of the cold. And the heroes of Azeroth are looking like a tasty meal...",
		dungeonEncounterID=2668,
		uiMapID=2194,
		pin={x=0.36,y=0.355},
		difficultyIDs={2,8,23,216},
		npcIDs={197294,197662},
		displayIDs={103254,111245,111284,112066},
		loot={
			{itemID=207836,diffs={},faction=-1},
			{itemID=207817,diffs={},faction=-1},
			{itemID=207912,diffs={},faction=-1},
			{itemID=207983,diffs={},faction=-1},
			{itemID=207992,diffs={},faction=-1},
			{itemID=207921,diffs={},faction=-1},
		},
		sections={
			{id=26542,title="Overview",body="Blight of Galakrond oozes |cFF2959D3|Hspell:407057|h[Blight Seep]|h|r during battle while assaulting players with |cFF2959D3|Hspell:406886|h[Corrosive Infusion]|h|r. The blight uses |cFF2959D3|Hspell:407159|h[Blight Reclamation]|h|r to re-energize.\n\nThe blight transfers into a new host at $415576s1% health and $415576s2% health, gaining new abilities."},
			{id=27223,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:407406|h[Corrosion]|h|r causes |cFF2959D3|Hspell:418348|h[Corrupted Mind]|h|r upon expiration.\n$bullet; |cFF2959D3|Hspell:408029|h[Necrofrost]|h|r is vulnerable to damage.",difficultyIDs={8,23}},
			{id=26543,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:407406|h[Corrosion]|h|r transfers on contact with other players.\n$bullet; |cFF2959D3|Hspell:408029|h[Necrofrost]|h|r is vulnerable to damage.",difficultyIDs={2}},
			{id=27224,title="Healers",body="$bullet; |cFF2959D3|Hspell:407406|h[Corrosion]|h|r causes |cFF2959D3|Hspell:418348|h[Corrupted Mind]|h|r upon expiration.\n$bullet; |cFF2959D3|Hspell:407978|h[Necrotic Winds]|h|r inflicts significant damage to all players.",difficultyIDs={8,23}},
			{id=26544,title="Healers",body="$bullet; |cFF2959D3|Hspell:407406|h[Corrosion]|h|r transfers on contact with other players.\n$bullet; |cFF2959D3|Hspell:407978|h[Necrotic Winds]|h|r inflicts significant damage to all players.",difficultyIDs={2}},
			{id=26545,title="Tanks",body="$bullet; |cFF2959D3|Hspell:407057|h[Blight Seep]|h|r forms continuously under afflicted creatures.\n$bullet; |cFF2959D3|Hspell:407159|h[Blight Reclamation]|h|r removes |cFF2959D3|Hspell:407406|h[Corrosion]|h|r."},
			{id=26547,title="Blight of Galakrond",body="The blight uses |cFF2959D3|Hspell:415097|h[Malignant Transferal]|h|r to take over hosts. It transfers into Ahnzon at $415576s1% health, and transfers into Loszkeleth and Dazhak at $415576s2% health."},
			{id=26561,title="Section 11"},
			{id=27226,title="Section 12",difficultyIDs={8,23}},
			{id=27295,title="Section 24"},
			{id=26563,title="Section 12",difficultyIDs={2}},
			{id=26562,title="Section 13"},
			{id=26564,title="Section 14"},
			{id=26548,title="Section 6"},
			{id=26556,title="Ahnzon",body="Blight of Galakrond reanimates Ahnzon at $415576s1% health, gaining |cFF2959D3|Hspell:407978|h[Necrotic Winds]|h|r."},
			{id=26566,title="Section 15"},
			{id=27379,title="Section 22"},
			{id=26557,title="Loszkeleth",body="Blight of Galakrond reanimates Loszkeleth, gaining |cFF2959D3|Hspell:408029|h[Necrofrost]|h|r."},
			{id=26567,title="Section 16"},
			{id=26558,title="Dazhak",body="Blight of Galakrond reanimates Dazhak, gaining |cFF2959D3|Hspell:408141|h[Incinerating Blightbreath]|h|r and |cFF2959D3|Hspell:413590|h[Noxious Ejection]|h|r.\n\nDazhak acts as |cFF2959D3|Hspell:417469|h[Loszkeleth's Support]|h|r."},
			{id=26568,title="Section 17"},
			{id=27137,title="Section 17"},
		},
	},
	[2536]={
		encounterID=2536,
		instanceID=1209,
		order=6,
		name="Morchie",
		lore="Morchie is the alternate form of Chromie, created by a timeline where Murozond rose and the infinites reigned supreme. And it so happens that she rather enjoys being part of the true timeline, and would like to keep it that way. Unfortunately, the heroes of Azeroth keep getting in the way of her plans.",
		dungeonEncounterID=2671,
		uiMapID=2196,
		pin={x=0.4882,y=0.5399},
		difficultyIDs={2,8,23,216},
		npcIDs={208464},
		displayIDs={111457},
		loot={
			{itemID=207862,diffs={},faction=-1},
			{itemID=207579,diffs={},faction=-1},
			{itemID=207986,diffs={},faction=-1},
			{itemID=207997,diffs={},faction=-1},
			{itemID=207939,diffs={},faction=-1},
			{itemID=207946,diffs={},faction=-1},
			{itemID=207824,diffs={},faction=-1},
		},
		sections={
			{id=26573,title="Overview",body="Morchie shapes the fabric of time around her, summoning alternate versions of herself to give players |cFF2959D3|Hspell:403891|h[More Problems!]|h|r, and forcing them to battle with some |cFF2959D3|Hspell:405279|h[Familiar Faces]|h|r.\n\nWhen not summoning threats from other timelines, Morchie also creates numerous |cFF2959D3|Hspell:406481|h[Time Traps]|h|r that can ensnare friend and foe alike."},
			{id=26574,title="Tanks",body="$bullet; |cFF2959D3|Hspell:404916|h[Sand Blast]|h|r inflicts heavy damage in a line in front of Morchie.\n$bullet; Only the original Morchie succeeds in casting |cFF2959D3|Hspell:404365|h[Dragon's Breath]|h|r. Look closely to distinguish the original her from the imposters.\n$bullet; |cFF2959D3|Hspell:405279|h[Familiar Faces]|h|r from other timelines attack only the player who corresponds to them in this timeline."},
			{id=26575,title="Damage Dealers",body="$bullet; Only the original Morchie succeeds in casting |cFF2959D3|Hspell:404365|h[Dragon's Breath]|h|r. Look closely to distinguish the original her from the imposters.\n$bullet; |cFF2959D3|Hspell:405279|h[Familiar Faces]|h|r from other timelines attack only the player who corresponds to them in this timeline."},
			{id=26576,title="Healers",body="$bullet; |cFF2959D3|Hspell:406100|h[Temporal Backlash]|h|r inflicts damage to all players whenever a |cFF2959D3|Hspell:406481|h[Time Trap]|h|r is triggered.\n$bullet; Only the original Morchie succeeds in casting |cFF2959D3|Hspell:404365|h[Dragon's Breath]|h|r. Look closely to distinguish the original her from the imposters.\n$bullet; |cFF2959D3|Hspell:405279|h[Familiar Faces]|h|r from other timelines attack only the player who corresponds to them in this timeline."},
			{id=26588,title="Section 5"},
			{id=26589,title="Section 6",body="$[8,23\n\nAll Morchies begin to cast |cFF2959D3|Hspell:404365|h[Dragon's Breath]|h|r. Just before the cast time ends, the original Morchie sends the alternates back to their own timelines.$]"},
			{id=26590,title="Section 7"},
			{id=27380,title="Section 15"},
			{id=26591,title="Section 8",body="$; \n\nOn subsequent casts, Morchie restores her minions to full health and removes any harmful effects."},
			{id=26592,title="Familiar Face"},
			{id=27377,title="Section 10"},
			{id=26593,title="Section 10"},
			{id=26594,title="Section 11"},
			{id=27378,title="Section 12",body="Time Traps trigger on contact with players, rooting them in place for 30 seconds.\n\nFamiliar Faces that trigger a Time Trap are suspended in time until Morchie frees them."},
			{id=26595,title="Section 12"},
		},
	},
	[2537]={
		encounterID=2537,
		instanceID=1209,
		order=4,
		name="Iridikron the Stonescaled",
		lore="Iridikron is a powerful Incarnate who wields both the power and patience of earth itself. He wishes to topple the Aspects and rid the world of the titan's influence. However, his exact plans to do so are not yet known. Why has he joined forces with the infinites? Whatever the answer, he must be stopped.",
		dungeonEncounterID=2669,
		uiMapID=2194,
		pin={x=0.4517,y=0.784},
		difficultyIDs={2,8,23,216},
		npcIDs={109076,114026},
		displayIDs={73034,105326},
		loot={
			{itemID=207911,diffs={},faction=-1},
			{itemID=207820,diffs={},faction=-1},
			{itemID=207920,diffs={},faction=-1},
			{itemID=207528,diffs={},faction=-1},
			{itemID=208321,diffs={},faction=-1},
			{itemID=207897,diffs={},faction=-1},
		},
		sections={
			{id=26577,title="Overview",body="As a |cFF2959D3|Hspell:409692|h[Patient Tactician]|h|r, Iridikron weakens his opponents while gathering energy. At 100 energy, he unleashes |cFF2959D3|Hspell:414184|h[Cataclysmic Obliteration]|h|r.\n\nDuring battle, Iridikron exhausts Chromie with |cFF2959D3|Hspell:409261|h[Extinction Blast]|h|r and then attempts to kill her with |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r."},
			{id=27234,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:409456|h[Earthsurge]|h|r inflicts increasing damage over time.\n$bullet; |cFF2959D3|Hspell:409261|h[Extinction Blast]|h|r inflicts lethal damage without Chromie's |cFF2959D3|Hspell:414330|h[Timeline Protection]|h|r.\n$bullet; |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r inflicts lethal damage to Chromie unless players reduce its force.",difficultyIDs={8,23}},
			{id=26578,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:409456|h[Earthsurge]|h|r radiates damaging energy waves while Iridikron remains shielded.\n$bullet; |cFF2959D3|Hspell:409261|h[Extinction Blast]|h|r inflicts lethal damage without Chromie's |cFF2959D3|Hspell:414330|h[Timeline Protection]|h|r.\n$bullet; |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r inflicts lethal damage to Chromie unless players reduce its force.",difficultyIDs={2}},
			{id=27235,title="Healers",body="$bullet; |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r injures Chromie.\n$bullet; |cFF2959D3|Hspell:409456|h[Earthsurge]|h|r and |cFF2959D3|Hspell:414184|h[Cataclysmic Obliteration]|h|r radiate damaging energy waves.\n$bullet; |cFF2959D3|Hspell:409261|h[Extinction Blast]|h|r inflicts lethal damage without Chromie's |cFF2959D3|Hspell:414330|h[Timeline Protection]|h|r."},
			{id=27236,title="Tanks",body="$bullet; Intercepting |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r saves allies from |cFF2959D3|Hspell:414604|h[Stonecrack]|h|r.\n$bullet; |cFF2959D3|Hspell:414075|h[Crushing Onslaught]|h|r rapidly increases the damage taken by Iridikron's target.\n$bullet; |cFF2959D3|Hspell:409635|h[Pulverizing Exhalation]|h|r causes creations of stone to erupt from the earth.",difficultyIDs={8,23}},
			{id=26580,title="Tanks",body="$bullet; |cFF2959D3|Hspell:414075|h[Crushing Onslaught]|h|r rapidly increases the damage taken by Iridikron's target.\n$bullet; |cFF2959D3|Hspell:414535|h[Stonecracker Barrage]|h|r inflicts lethal damage to Chromie unless players reduce its force.\n$bullet; |cFF2959D3|Hspell:409456|h[Earthsurge]|h|r radiates damaging energy waves while Iridikron remains shielded.",difficultyIDs={2}},
			{id=26642,title="Section 7"},
