		instanceID=1209,
		order=8,
		name="Chrono-Lord Deios",
		lore="At long last, the infinite dragonflight shall usher in a new dawn for the world of Azeroth. Chrono-Lord Deios has traveled far into the past to ensure that Murozond shall rise. The heroes of Azeroth have already seen him succeed once. This time, can they stop him?",
		dungeonEncounterID=2673,
		uiMapID=2194,
		pin={x=0.5079,y=0.5651},
		difficultyIDs={2,8,23,216},
		npcIDs={199000},
		displayIDs={106056,112511,112687},
