		sections={
			{id=26581,title="Overview",body="Deios begins the infinite dawn, summoning Infinite Keepers who create stable time rifts, invading this timeline with Time-Displaced Troopers from other timelines. After summoning 4 Infinite Keepers, Deios takes to the skies.\n\nDeios lands once all portals close, beginning his onslaught against Nozdormu while the other proto-dragon allies pelt Deios from the skies. \n\nWhen Deios reaches $416276s1% health the proto-dragon allies land and free Nozdormu, battling Deios head on."},
			{id=26582,title="Tanks",body="$bullet;Aim |cFF2959D3|Hspell:416139|h[Temporal Breath]|h|r away from allies.\n$bullet;Summoned Infinite Keepers blast their primary target with |cFF2959D3|Hspell:411763|h[Infinite Blast]|h|r.\n$bullet;Standing under |cFF2959D3|Hspell:410904|h[Infinity Orb]|h|rs as they fall can stagger the application of |cFF2959D3|Hspell:410908|h[Infinity Nova]|h|r's vulnerability."},
			{id=26583,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:416139|h[Temporal Breath]|h|r inflicts significant damage in a significant area.\n$bullet;Defeat summoned Infinite Keepers to return Deios to the ground from |cFF2959D3|Hspell:416261|h[Collapsing Time Rift]|h|r.\n$bullet;Standing under |cFF2959D3|Hspell:410904|h[Infinity Orb]|h|rs as they fall can stagger the application of |cFF2959D3|Hspell:410908|h[Infinity Nova]|h|r's vulnerability."},
			{id=26584,title="Healers",body="$bullet;Infinite Keepers' |cFF2959D3|Hspell:412027|h[Chronal Burn]|h|r inflicts significant damage.\n$bullet;Standing under |cFF2959D3|Hspell:410904|h[Infinity Orb]|h|rs as they fall can stagger the application of |cFF2959D3|Hspell:410908|h[Infinity Nova]|h|r's vulnerability.\n$bullet;|cFF2959D3|Hspell:416139|h[Temporal Breath]|h|r inflicts significant damage in a significant area."},
			{id=26751,title="Stage 1: We Are Infinite",body="Deios summons Infinite Keepers, then takes to the skies, creating |cFF2959D3|Hspell:410904|h[Infinity Orb]|h|rs from above.\n\nUpon reaching $412335s1% health Deios lands."},
			{id=26752,title="Chrono-Lord Deios"},
