		sections={
			{id=27237,title="Overview",body="Larodar summons |cFF2959D3|Hspell:417666|h[Fiery Treants]|h|r and |cFF2959D3|Hspell:418654|h[Scorching Roots]|h|r to spread |cFF2959D3|Hspell:417610|h[Burning Ground]|h|r. Upon reaching 100 energy, Larodar envelops the arena in flame with |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r.\n\nAfter 3 casts of |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r, Larodar channels |cFF2959D3|Hspell:421316|h[Consuming Flame]|h|r and transforms into the |cFF2959D3|Hspell:421998|h[Avatar of Ash]|h|r. |cFF2959D3|Hspell:427252|h[Falling Embers]|h|r fall from above as Larodar attempts to cleanse his enemies with |cFF2959D3|Hspell:421326|h[Flash Fire]|h|r."},
			{id=27238,title="Tanks",body="$bullet;|cFF2959D3|Hspell:418637|h[Furious Charge]|h|r applies |cFF2959D3|Hspell:423719|h[Nature's Fury]|h|r and inflicts less damage the further his target is.\n$bullet;|cFF2959D3|Hspell:421594|h[Smoldering Suffocation]|h|r prevents all healing received but drains health from nearby allies.\n$bullet;|cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r drastically reduce damage taken from |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r."},
			{id=27240,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:417666|h[Fiery Treants]|h|r transform into |cFF2959D3|Hspell:417667|h[Charred Treants]|h|r and |cFF2959D3|Hspell:418657|h[Scorching Brambles]|h|r transform into |cFF2959D3|Hspell:418655|h[Charred Brambles]|h|r when killed.\n$bullet;|cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r drastically reduce damage taken from |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r.\n$bullet;|cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r douses |cFF2959D3|Hspell:417610|h[Burning Ground]|h|r.",difficultyIDs={14,17}},
			{id=28232,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:417666|h[Fiery Treants]|h|r transform into |cFF2959D3|Hspell:417667|h[Charred Treants]|h|r and |cFF2959D3|Hspell:418657|h[Scorching Brambles]|h|r transform into |cFF2959D3|Hspell:418655|h[Charred Brambles]|h|r when killed.\n$bullet;|cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r drastically reduce damage taken from |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r.\n$bullet;|cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r douses |cFF2959D3|Hspell:417610|h[Burning Ground]|h|r and |cFF2959D3|Hspell:418654|h[Scorching Roots]|h|r.",difficultyIDs={15,16}},
			{id=27239,title="Healers",body="$bullet;|cFF2959D3|Hspell:417667|h[Charred Treants]|h|r transform into |cFF2959D3|Hspell:417668|h[Renewed Treants]|h|r and |cFF2959D3|Hspell:418655|h[Charred Brambles]|h|r transform into |cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r when healed to full.\n$bullet;|cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r drastically reduce damage taken from |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r.\n$bullet;|cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r douses |cFF2959D3|Hspell:417610|h[Burning Ground]|h|r.\n$bullet;|cFF2959D3|Hspell:421326|h[Flash Fire]|h|r-afflicted players become |cFF2959D3|Hspell:427306|h[Encased in Ash]|h|r if the absorb expires.",difficultyIDs={14,17}},
			{id=28233,title="Healers",body="$bullet;|cFF2959D3|Hspell:417667|h[Charred Treants]|h|r transform into |cFF2959D3|Hspell:417668|h[Renewed Treants]|h|r and |cFF2959D3|Hspell:418655|h[Charred Brambles]|h|r transform into |cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r when healed to full.\n$bullet;|cFF2959D3|Hspell:418653|h[Renewed Bramble Barriers]|h|r drastically reduce damage taken from |cFF2959D3|Hspell:417634|h[Raging Inferno]|h|r.\n$bullet;|cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r douses |cFF2959D3|Hspell:417610|h[Burning Ground]|h|r and |cFF2959D3|Hspell:418654|h[Scorching Roots]|h|r.\n$bullet;|cFF2959D3|Hspell:421326|h[Flash Fire]|h|r-afflicted players become |cFF2959D3|Hspell:427306|h[Encased in Ash]|h|r if the absorb expires.",difficultyIDs={15,16}},
			{id=27241,title="Stage One: The Cycle of Flame"},
			{id=27967,title="Section 48",difficultyIDs={16}},
			{id=27907,title="Seed of Life",body="The Seed of Life lays dormant while it has zero energy. Renewed Treants' channel |cFF2959D3|Hspell:424997|h[Nature's Gift]|h|r causing the seed to blossom."},
			{id=27908,title="Section 46",body="$[!15\n\nOn Heroic and Mythic difficulties, the Seed of Life causes players who form a bond to gain Dream Fatigue.$]$[!16\n\nOn Heroic and Mythic difficulties, the Seed of Life causes players who form a bond to gain Dream Fatigue.$]"},
			{id=27914,title="Section 47",difficultyIDs={15,16}},
			{id=27313,title="Section 10"},
			{id=27321,title="Fiery Treant",body="Fiery Treants seek to spread flame throughout the temple and leave behind Burning Ground.\n\nWhen killed, they transform into a Charred Treant."},
			{id=27330,title="Section 23"},
			{id=28145,title="Section 49"},
			{id=27331,title="Section 24"},
			{id=27322,title="Charred Treant",body="Charred Treants are inert and can be healed.\n\nWhen they reach full health, they transform into a Renewed Treant."},
			{id=27323,title="Renewed Treant",body="Friendly Renewed Treants channel Nature's Gift, sacrificing their own life to empower the Seed of Life."},
			{id=27332,title="Section 25"},
			{id=27312,title="Section 9"},
			{id=28146,title="Scorching Roots",body="Scorching Roots fixate on random players, pursuing them relentlessly and speed over time.\n\nWhen killed, they transform into Charred Brambles.",difficultyIDs={14,17}},
			{id=28147,title="Section 48"},
			{id=27324,title="Scorching Roots",body="Scorching Roots fixate on random players, pursuing them relentlessly and speed over time.\n\nWhen killed, they transform into Charred Brambles.$[!15\n\nOn Heroic and Mythic difficulties, Scorched Roots remain untargetable until doused with |cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r.$]$[!16\n\nOn Heroic and Mythic difficulties, Scorched Roots remain untargetable until doused with |cFF2959D3|Hspell:425249|h[Dream Blossom]|h|r.$]",difficultyIDs={15,16}},
			{id=28086,title="Section 48"},
			{id=27326,title="Charred Brambles",body="Charred Brambles are inert and can be healed.\n\nWhen they reach full health, they transform into a Renewed Bramble Barrier."},
			{id=27327,title="Renewed Bramble Barrier",body="Renewed Bramble Barriers provide protection against Raging Inferno.\n\nWhen destroyed, they erupt in Explosive Bark."},
