		sections={
			{id=27296,title="Overview",body="Players battle against the Council of Dreams: the fearsome werebear Urctos, the naturalist dryad Aerwynn and the trickster faerie dragon Pip.\n\nAt 100 energy each council member unleashes their strongest attacks, casting |cFF2959D3|Hspell:420525|h[Blind Rage]|h|r, |cFF2959D3|Hspell:421292|h[Constricting Thicket]|h|r or |cFF2959D3|Hspell:421029|h[Song of the Dragon]|h|r respectively.\n\nUpon reaching 1 health, that council member taps into the Dream, casting |cFF2959D3|Hspell:418187|h[Rebirth]|h|r, but fail if their allies suffer the same fate."},
			{id=28171,title="Tanks",body="$bullet;Urctos' |cFF2959D3|Hspell:421020|h[Agonizing Claws]|h|r inflicts Physical damage, leaving the target vulnerable to |cFF2959D3|Hspell:421020|h[Agonizing Claws]|h|r.\n$bullet;Urctos' |cFF2959D3|Hspell:420946|h[Barreling Charge]|h|r inflicts reduced damage as more players bear the load and interrupts Aerwynn's |cFF2959D3|Hspell:421292|h[Constricting Thicket]|h|r.\n$bullet;Pip's |cFF2959D3|Hspell:421029|h[Song of the Dragon]|h|r applies |cFF2959D3|Hspell:421032|h[Captivating Finale]|h|r if not removed.",difficultyIDs={14,17}},
			{id=27297,title="Tanks",body="$bullet;Urctos' |cFF2959D3|Hspell:421020|h[Agonizing Claws]|h|r inflicts Physical damage in a frontal cone, leaving the target vulnerable to |cFF2959D3|Hspell:421020|h[Agonizing Claws]|h|r.\n$bullet;Urctos' |cFF2959D3|Hspell:420946|h[Barreling Charge]|h|r inflicts reduced damage as more players bear the load and interrupts Aerwynn's |cFF2959D3|Hspell:421292|h[Constricting Thicket]|h|r.\n$bullet;Pip's |cFF2959D3|Hspell:421029|h[Song of the Dragon]|h|r applies |cFF2959D3|Hspell:421032|h[Captivating Finale]|h|r if not removed.",difficultyIDs={15,16}},
			{id=27298,title="Damage Dealers",body="$bullet;Upon removal, |cFF2959D3|Hspell:418720|h[Polymorph Bomb]|h|r afflicts nearby players, but also affects Urctos during |cFF2959D3|Hspell:420525|h[Blind Rage]|h|r.\n$bullet;Urctos' |cFF2959D3|Hspell:420946|h[Barreling Charge]|h|r inflicts reduced damage as more players bear the load and interrupts Aerwynn's |cFF2959D3|Hspell:421292|h[Constricting Thicket]|h|r.\n$bullet;Pip's |cFF2959D3|Hspell:421029|h[Song of the Dragon]|h|r applies |cFF2959D3|Hspell:421032|h[Captivating Finale]|h|r if not removed."},
			{id=28172,title="Healers",body="$bullet;Upon removal, |cFF2959D3|Hspell:418720|h[Polymorph Bomb]|h|r afflicts nearby players, but also affects Urctos during |cFF2959D3|Hspell:420525|h[Blind Rage]|h|r.\n$bullet;Pip's |cFF2959D3|Hspell:421029|h[Song of the Dragon]|h|r applies |cFF2959D3|Hspell:421032|h[Captivating Finale]|h|r if not removed.\n$bullet;Urctos' |cFF2959D3|Hspell:421020|h[Agonizing Claws]|h|r inflicts high Physical damage.",difficultyIDs={14,17}},
