		sections={
			{id=27453,title="Overview",body="Smolderon showcases his worth as a Firelord by utilizing his weapon Emberscar to great effect. He marks his enemies with |cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r while also igniting them with |cFF2959D3|Hspell:421455|h[Overheated]|h|r.\n\nUpon reaching 100 energy, Smolderon slams Emberscar into the ground. He then feasts on players' essence while overwhelming them with  |cFF2959D3|Hspell:422172|h[World In Flames]|h|r."},
			{id=28120,title="Tanks",body="$bullet;|cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r marks all players struck with |cFF2959D3|Hspell:421656|h[Cauterizing Wound]|h|r which absorbs a large amount of healing.\n$bullet;|cFF2959D3|Hspell:422277|h[Devour Essence]|h|r draws |cFF2959D3|Hspell:423904|h[Living Flames]|h|r out of players afflicted with |cFF2959D3|Hspell:421643|h[Emberscar's Mark]|h|r.",difficultyIDs={14,17}},
			{id=27454,title="Tanks",body="$bullet;|cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r afflicts the primary target with |cFF2959D3|Hspell:422577|h[Searing Aftermath]|h|r which explodes for less damage the further away the target is.\n$bullet;|cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r marks all players struck with |cFF2959D3|Hspell:421656|h[Cauterizing Wound]|h|r which absorbs a large amount of healing.\n$bullet;|cFF2959D3|Hspell:422277|h[Devour Essence]|h|r draws |cFF2959D3|Hspell:423904|h[Living Flames]|h|r out of players afflicted with |cFF2959D3|Hspell:421643|h[Emberscar's Mark]|h|r.",difficultyIDs={15,16}},
			{id=27455,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r marks all players struck with |cFF2959D3|Hspell:421656|h[Cauterizing Wound]|h|r which absorbs a large amount of healing.\n$bullet;|cFF2959D3|Hspell:422277|h[Devour Essence]|h|r draws |cFF2959D3|Hspell:423904|h[Living Flames]|h|r out of players afflicted with |cFF2959D3|Hspell:421643|h[Emberscar's Mark]|h|r.\n$bullet;|cFF2959D3|Hspell:421455|h[Overheated]|h|r inflicts damage to all players nearby the target."},
			{id=27456,title="Healers",body="$bullet;|cFF2959D3|Hspell:422067|h[Blazing Soul]|h|r causes |cFF2959D3|Hspell:420950|h[Blistering Heat]|h|r to inflict heavy damage to all players.\n$bullet;|cFF2959D3|Hspell:421343|h[Brand of Damnation]|h|r marks all players struck with |cFF2959D3|Hspell:421656|h[Cauterizing Wound]|h|r which absorbs a large amount of healing.\n$bullet;|cFF2959D3|Hspell:422277|h[Devour Essence]|h|r draws |cFF2959D3|Hspell:423904|h[Living Flames]|h|r out of players afflicted with |cFF2959D3|Hspell:421643|h[Emberscar's Mark]|h|r."},
			{id=27637,title="Stage One: The Firelord's Fury"},
