		sections={
			{id=28326,title="Overview",body="As a master shapeshifter, Tindral assaults players in various Druid forms.\n\nIn his humanoid form, Tindral roots players with |cFF2959D3|Hspell:424495|h[Mass Entanglement]|h|r and bombards players with |cFF2959D3|Hspell:420236|h[Falling Stars]|h|r.\n\nShapeshifting into his Moonkin form, Tindral unleashes |cFF2959D3|Hspell:420240|h[Sunflame]|h|r on all players and summons |cFF2959D3|Hspell:421398|h[Fire Beam]|h|r that scorches the platform.\n\nAs the Treant of the Flame, Tindral pulses |cFF2959D3|Hspell:424579|h[Suppressive Ember]|h|r and sears players with |cFF2959D3|Hspell:423266|h[Flaming Germination]|h|r.\n\nBecoming the Owl of the Flame leaves behind |cFF2959D3|Hspell:422509|h[Empowered Feather]|h|r, allowing players to dragonride within The Blessed Boughs."},
			{id=28327,title="Tanks",body="$bullet; |cFF2959D3|Hspell:421992|h[Searing Wrath]|h|r is applied on every melee strike and stacks.\n$bullet; |cFF2959D3|Hspell:423260|h[Blazing Mushroom]|h|r inflicts high damage to all players if it fails to hit a player.\n$bullet; |cFF2959D3|Hspell:421398|h[Fire Beam]|h|r inflicts Fire damage to players within.",difficultyIDs={14,15,17}},
			{id=28328,title="Tanks",body="$bullet; |cFF2959D3|Hspell:421992|h[Searing Wrath]|h|r is applied on every melee strike and stacks.\n$bullet; |cFF2959D3|Hspell:423260|h[Blazing Mushroom]|h|r and |cFF2959D3|Hspell:426686|h[Poisonous Mushroom]|h|r inflict high damage to all players if they fail to hit a player.\n$bullet; |cFF2959D3|Hspell:421398|h[Fire Beam]|h|r inflicts Fire damage to players within its area.",difficultyIDs={16}},
			{id=28329,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:424140|h[Supernova]|h|r is interrupted when its absorb shield is depleted.\n$bullet; |cFF2959D3|Hspell:424497|h[Mass Entanglement]|h|r holds players in place until the roots are destroyed.\n$bullet; |cFF2959D3|Hspell:424581|h[Fiery Growth]|h|r creates |cFF2959D3|Hspell:425451|h[Scorching Ground]|h|r when dispelled.",difficultyIDs={14,15,16}},
			{id=28330,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:424140|h[Supernova]|h|r is interrupted when its absorb shield is depleted.\n$bullet; |cFF2959D3|Hspell:424497|h[Mass Entanglement]|h|r holds players in place until the roots are destroyed.",difficultyIDs={17}},
			{id=28331,title="Healers",body="$bullet; |cFF2959D3|Hspell:424581|h[Fiery Growth]|h|r creates |cFF2959D3|Hspell:425451|h[Scorching Ground]|h|r when dispelled.\n$bullet; |cFF2959D3|Hspell:424579|h[Suppressive Ember]|h|r is used in Treant form and absorbs a substantial amount of healing.\n$bullet; Tindral continuously blasts the group with |cFF2959D3|Hspell:420240|h[Sunflame]|h|r while in his Moonkin form.",difficultyIDs={14,15}},
			{id=28332,title="Healers",body="$bullet; |cFF2959D3|Hspell:424579|h[Suppressive Ember]|h|r is used in Treant form and absorbs a substantial amount of healing.\n$bullet; Tindral continuously blasts the group with |cFF2959D3|Hspell:420240|h[Sunflame]|h|r while in his Moonkin form.",difficultyIDs={17}},
			{id=28333,title="Healers",body="$bullet; |cFF2959D3|Hspell:429166|h[Astral Heat]|h|r gradually increases damage taken from |cFF2959D3|Hspell:424140|h[Supernova]|h|r.\n$bullet; |cFF2959D3|Hspell:424581|h[Fiery Growth]|h|r creates |cFF2959D3|Hspell:425451|h[Scorching Ground]|h|r when dispelled.\n$bullet; |cFF2959D3|Hspell:424579|h[Suppressive Ember]|h|r is used in Treant form and absorbs a substantial amount of healing.\n$bullet; Tindral continuously blasts the group with |cFF2959D3|Hspell:420240|h[Sunflame]|h|r while in his Moonkin form.",difficultyIDs={16}},
			{id=27488,title="Stage One: Moonkin of the Flame"},
			{id=27661,title="Tindral Sageswift"},
			{id=28367,title="Section 60",difficultyIDs={14,15,17}},
			{id=28370,title="Section 60",body="$[!16\n\nIn Mythic difficulty, if the fiery vine fails to root a player or if the root is removed before it is destroyed, a Scorched Treant is formed at its location.",difficultyIDs={16}},
			{id=28371,title="Scorched Treant",difficultyIDs={16}},
